package gitgraph

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Options holds all CLI options
type Options struct {
	Path                   string
	Model                  string
	MaxCount               int
	Color                  string
	NoColor                bool
	Wrap                   []string
	Format                 string
	Reverse                bool
	Local                  bool
	SVG                    bool
	Debug                  bool
	Sparse                 bool
	Style                  string
	SkipRepoOwnerValidation bool
	// Subcommand
	ModelSubcmd *ModelSubcmd
}

type ModelSubcmd struct {
	ModelName string
	List      bool
}

// ParseArgs parses the command-line arguments
func ParseArgs(args []string) (*Options, error) {
	opts := &Options{
		MaxCount: -1,
		Color:    "auto",
		Format:   "oneline",
		Style:    "normal",
		Wrap:     nil,
	}

	i := 0
	for i < len(args) {
		arg := args[i]

		// Handle --help/-h
		if arg == "--help" || arg == "-h" {
			printHelp()
			os.Exit(0)
		}

		// Handle --version/-V
		if arg == "--version" || arg == "-V" {
			fmt.Println("git-graph 0.7.0")
			os.Exit(0)
		}

		// Handle subcommands
		if arg == "model" || arg == "help" {
			if arg == "help" {
				// Check what follows
				if i+1 < len(args) {
					sub := args[i+1]
					if sub == "model" {
						printModelHelp()
						os.Exit(0)
					}
				}
				printHelp()
				os.Exit(0)
			}
			// model subcommand
			sub := &ModelSubcmd{}
			i++
			for i < len(args) {
				a := args[i]
				if a == "--list" || a == "-l" {
					sub.List = true
				} else if a == "--help" || a == "-h" {
					printModelHelp()
					os.Exit(0)
				} else if !strings.HasPrefix(a, "-") {
					sub.ModelName = a
				} else {
					return nil, fmt.Errorf("unexpected argument '%s' found\n\nUsage: executable model [OPTIONS] [model]\n\nFor more information, try '--help'.", a)
				}
				i++
			}
			opts.ModelSubcmd = sub
			return opts, nil
		}

		// Handle flags
		switch arg {
		case "-p", "--path":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--path requires a value")
			}
			i++
			opts.Path = args[i]
		case "-m", "--model":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--model requires a value")
			}
			i++
			opts.Model = args[i]
		case "-n", "--max-count":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--max-count requires a value")
			}
			i++
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid max-count: %s", args[i])
			}
			opts.MaxCount = n
		case "--color":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--color requires a value")
			}
			i++
			opts.Color = args[i]
		case "--no-color":
			opts.NoColor = true
		case "-f", "--format":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--format requires a value")
			}
			i++
			opts.Format = args[i]
		case "-r", "--reverse":
			opts.Reverse = true
		case "-l", "--local":
			opts.Local = true
		case "--svg":
			opts.SVG = true
		case "-d", "--debug":
			opts.Debug = true
		case "-S", "--sparse":
			opts.Sparse = true
		case "-s", "--style":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--style requires a value")
			}
			i++
			opts.Style = args[i]
		case "-w", "--wrap":
			// Wrap takes optional args
			wrapArgs := []string{}
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				i++
				wrapArgs = append(wrapArgs, args[i])
			}
			opts.Wrap = wrapArgs
		case "--skip-repo-owner-validation":
			opts.SkipRepoOwnerValidation = true
		default:
			if strings.HasPrefix(arg, "--") || (strings.HasPrefix(arg, "-") && len(arg) == 2) {
				return nil, fmt.Errorf("unexpected argument '%s' found\n\nUsage: executable [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.", arg)
			}
			return nil, fmt.Errorf("unexpected argument '%s' found\n\nUsage: executable [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.", arg)
		}
		i++
	}

	return opts, nil
}

func printHelp() {
	fmt.Print(`Structured Git graphs for your branching model.
    https://github.com/mlange-42/git-graph

EXAMPES:
    git-graph                   -> Show graph
    git-graph --style round     -> Show graph in a different style
    git-graph --model <model>   -> Show graph using a certain <model>
    git-graph model --list      -> List available branching models
    git-graph model             -> Show repo's current branching models
    git-graph model <model>     -> Permanently set model <model> for this repo

Usage: executable [OPTIONS] [COMMAND]

Commands:
  model  Prints or permanently sets the branching model for a repository.
  help   Print this message or the help of the given subcommand(s)

Options:
  -p, --path <path>
          Open repository from this path or above. Default '.'

      --skip-repo-owner-validation
          Skip owner validation for the repository.
          This will turn off libgit2's owner validation, which may increase security risks.
          Please do not disable this validation for repositories you do not trust.

  -m, --model <model>
          Branching model. Available presets are [simple|git-flow|none].
          Default: git-flow. 
          Permanently set the model for a repository with
          > git-graph model <model>

  -n, --max-count <n>
          Maximum number of commits

      --color <color>
          Specify when colors should be used. One of [auto|always|never].
          Default: auto.

      --no-color
          Print without colors. Missing color support should be detected
          automatically (e.g. when piping to a file).
          Overrides option '--color'

  -w, --wrap [<wrap>...]
          Line wrapping for formatted commit text. Default: 'auto 0 8'
          Argument format: [<width>|auto|none[ <indent1>[ <indent2>]]]
          Examples:
              git-graph --wrap auto
              git-graph --wrap auto 0 8
              git-graph --wrap none
              git-graph --wrap 80
              git-graph --wrap 80 0 8
          'auto' uses the terminal's width if on a terminal.

  -f, --format <format>
          Commit format. One of [oneline|short|medium|full|"<string>"].
            (First character can be used as abbreviation, e.g. '-f m')
          Formatting placeholders for "<string>":
              %n    newline
              %H    commit hash
              %h    abbreviated commit hash
              %P    parent commit hashes
              %p    abbreviated parent commit hashes
              %d    refs (branches, tags)
              %s    commit summary
              %b    commit message body
              %B    raw body (subject and body)
              %an   author name
              %ae   author email
              %ad   author date
              %as   author date in short format 'YYYY-MM-DD'
              %cn   committer name
              %ce   committer email
              %cd   committer date
              %cs   committer date in short format 'YYYY-MM-DD'

              If you add a + (plus sign) after % of a placeholder,
                 a line-feed is inserted immediately before the expansion if
                 and only if the placeholder expands to a non-empty string.
              If you add a - (minus sign) after % of a placeholder, all
                 consecutive line-feeds immediately preceding the expansion are
                 deleted if and only if the placeholder expands to an empty string.
              If you add a ' ' (space) after % of a placeholder, a space is
                 inserted immediately before the expansion if and only if
                 the placeholder expands to a non-empty string.

              See also the respective git help: https://git-scm.com/docs/pretty-formats


  -r, --reverse
          Reverse the order of commits.

  -l, --local
          Show only local branches, no remotes.

      --svg
          Render graph as SVG instead of text-based.

  -d, --debug
          Additional debug output and graphics.

  -S, --sparse
          Print a less compact graph: merge lines point to target lines
          rather than merge commits.

  -s, --style <style>
          Output style. One of [normal/thin|round|bold|double|ascii].
            (First character can be used as abbreviation, e.g. '-s r')

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
`)
}

func printModelHelp() {
	fmt.Print(`Prints or permanently sets the branching model for a repository.

Usage: executable model [OPTIONS] [model]

Arguments:
  [model]  The branching model to be used. Available presets are [simple|git-flow|none].
           When not given, prints the currently set model.

Options:
  -l, --list  List all available branching models.
  -h, --help  Print help
`)
}

// ParseWrap parses the --wrap option
type WrapConfig struct {
	Width   int // 0 = auto, -1 = none
	Indent1 int
	Indent2 int
}

func ParseWrap(args []string) (*WrapConfig, error) {
	if len(args) == 0 {
		return &WrapConfig{Width: 0, Indent1: 0, Indent2: 8}, nil
	}

	cfg := &WrapConfig{Width: 0, Indent1: 0, Indent2: 8}

	// First arg is width
	switch args[0] {
	case "auto":
		cfg.Width = 0
	case "none":
		cfg.Width = -1
	default:
		n, err := strconv.Atoi(args[0])
		if err != nil {
			return nil, errors.New("Can't parse option --wrap '" + strings.Join(args, " ") + "' to integers.")
		}
		cfg.Width = n
	}

	if len(args) >= 2 {
		n, err := strconv.Atoi(args[1])
		if err != nil {
			return nil, errors.New("Can't parse option --wrap '" + strings.Join(args, " ") + "' to integers.")
		}
		cfg.Indent1 = n
	}
	if len(args) >= 3 {
		n, err := strconv.Atoi(args[2])
		if err != nil {
			return nil, errors.New("Can't parse option --wrap '" + strings.Join(args, " ") + "' to integers.")
		}
		cfg.Indent2 = n
	}
	return cfg, nil
}
GOEOF

