package gitgraph

import (
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// Run is the main entry point
func Run(args []string) error {
	opts, err := ParseArgs(args)
	if err != nil {
		return err
	}

	startTime := time.Now()

	// Handle model subcommand
	if opts.ModelSubcmd != nil {
		return handleModelSubcmd(opts)
	}

	// Find repository
	repoPath := "."
	if opts.Path != "" {
		repoPath = opts.Path
	}

	gitDir, err := findGitDir(repoPath)
	if err != nil {
		return fmt.Errorf("could not find repository at '%s'\n       Navigate into a repository before running git-graph, or use option --path", repoPath)
	}

	// Load branching model
	model, err := loadModel(gitDir, opts.Model)
	if err != nil {
		return err
	}

	// Determine color mode
	useColor := shouldUseColor(opts)

	// Determine style
	style, err := parseStyle(opts.Style)
	if err != nil {
		return err
	}

	// Determine format
	format, err := parseFormat(opts.Format)
	if err != nil {
		return err
	}

	// Parse wrap config
	wrapCfg := &WrapConfig{Width: 0, Indent1: 0, Indent2: 8}
	if opts.Wrap != nil {
		wrapCfg, err = ParseWrap(opts.Wrap)
		if err != nil {
			return err
		}
	}

	// Read git data
	workDir := filepath.Dir(gitDir)
	if isBarRepo(gitDir) {
		workDir = gitDir
	}

	gitData, err := readGitData(workDir, gitDir, opts.MaxCount, opts.Local)
	if err != nil {
		return err
	}

	constructTime := time.Since(startTime)

	// Build graph
	graph, err := buildGraph(gitData, model, opts.Sparse, opts.Reverse)
	if err != nil {
		return err
	}

	printTime := time.Now()

	// Print debug info
	if opts.Debug {
		printDebugInfo(graph, os.Stdout)
	}

	// Render output
	if opts.SVG {
		return renderSVG(graph, model, os.Stdout)
	}

	printStart := time.Now()
	err = renderText(graph, model, style, format, wrapCfg, useColor, opts.Debug, os.Stdout)
	if err != nil {
		return err
	}

	_ = constructTime
	_ = printTime
	_ = printStart

	if opts.Debug {
		constructMs := float64(constructTime.Microseconds()) / 1000.0
		printMs := float64(time.Since(printStart).Microseconds()) / 1000.0
		fmt.Fprintf(os.Stderr, "Graph construction: %.1f ms, printing: %.1f ms (%d commits)\n",
			constructMs, printMs, len(graph.Commits))
	}

	return nil
}

func handleModelSubcmd(opts *Options) error {
	sub := opts.ModelSubcmd

	if sub.List {
		// List all available models
		models, err := listModels()
		if err != nil {
			return err
		}
		for _, m := range models {
			fmt.Println(m)
		}
		return nil
	}

	// Find repository (needed for get/set operations)
	repoPath := "."
	if opts.Path != "" {
		repoPath = opts.Path
	}

	gitDir, err := findGitDir(repoPath)
	if err != nil {
		return fmt.Errorf("could not find repository at '%s'\n       Navigate into a repository before running git-graph, or use option --path", repoPath)
	}

	if sub.ModelName == "" {
		// Print current model
		m, err := getRepoModel(gitDir)
		if err != nil {
			return err
		}
		if m == "" {
			fmt.Print("No branching model set")
		} else {
			fmt.Print(m)
		}
		return nil
	}

	// Set model
	err = setRepoModel(gitDir, sub.ModelName)
	if err != nil {
		return err
	}
	fmt.Printf("Branching model set to '%s'", sub.ModelName)
	return nil
}

func isBarRepo(gitDir string) bool {
	// A bare repo has its git dir as the work dir
	return filepath.Base(gitDir) != ".git"
}

func shouldUseColor(opts *Options) bool {
	if opts.NoColor {
		return false
	}
	switch opts.Color {
	case "always":
		return true
	case "never":
		return false
	default: // "auto"
		// Check if stdout is a terminal
		fi, err := os.Stdout.Stat()
		if err != nil {
			return false
		}
		return (fi.Mode() & os.ModeCharDevice) != 0
	}
}

func parseStyle(s string) (StyleChars, error) {
	// Allow first character abbreviation
	if len(s) == 1 {
		switch s {
		case "n":
			s = "normal"
		case "t":
			s = "thin"
		case "r":
			s = "round"
		case "b":
			s = "bold"
		case "d":
			s = "double"
		case "a":
			s = "ascii"
		}
	}
	switch s {
	case "normal", "thin", "":
		return StyleNormal, nil
	case "round":
		return StyleRound, nil
	case "bold":
		return StyleBold, nil
	case "double":
		return StyleDouble, nil
	case "ascii":
		return StyleASCII, nil
	default:
		return StyleNormal, fmt.Errorf("unknown style: %s", s)
	}
}
