package gitgraph

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// CommitData holds raw commit information
type CommitData struct {
	Hash        string
	Parents     []string
	AuthorName  string
	AuthorEmail string
	AuthorDate  time.Time
	CommitterName  string
	CommitterEmail string
	CommitterDate  time.Time
	Subject     string
	Body        string
	Refs        []RefInfo // parsed refs
	RawRefs     string    // raw refs string from git
}

// RefInfo represents a branch, tag, or HEAD reference
type RefInfo struct {
	Name     string
	IsRemote bool
	IsTag    bool
	IsHEAD   bool
	HeadTarget string // if IsHEAD=true and HEAD -> branch, this is the target branch
}

// GitData holds all git repository data
type GitData struct {
	Commits   []*CommitData
	CommitMap map[string]int // hash -> index
}

// findGitDir finds the .git directory for a path
func findGitDir(path string) (string, error) {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}

	for {
		gitDir := filepath.Join(absPath, ".git")
		if fi, err := os.Stat(gitDir); err == nil {
			if fi.IsDir() {
				return gitDir, nil
			}
			// .git could be a file (worktree)
			return gitDir, nil
		}

		// Check if this is itself a bare repo
		if isBareGitDir(absPath) {
			return absPath, nil
		}

		parent := filepath.Dir(absPath)
		if parent == absPath {
			break
		}
		absPath = parent
	}
	return "", fmt.Errorf("not a git repository")
}

func isBareGitDir(path string) bool {
	// Check if it's a bare git repo by looking for HEAD file and objects dir
	headPath := filepath.Join(path, "HEAD")
	objPath := filepath.Join(path, "objects")

	_, err1 := os.Stat(headPath)
	_, err2 := os.Stat(objPath)
	return err1 == nil && err2 == nil
}

// readGitData reads all commit data from the git repository
func readGitData(workDir, gitDir string, maxCount int, localOnly bool) (*GitData, error) {
	// Use git log to get all commit data
	args := []string{
		"-C", workDir,
		"log",
		"--date-order",
		"--all",
		"--format=COMMIT:%H%n%P%n%an%n%ae%n%aI%n%cn%n%ce%n%cI%n%s%n%b%nENDBODY",
	}
	if maxCount > 0 {
		args = append(args, fmt.Sprintf("--max-count=%d", maxCount))
	}

	cmd := exec.Command("git", args...)
	cmd.Dir = workDir
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git log failed: %v", err)
	}

	commits, commitMap, err := parseGitLog(string(out))
	if err != nil {
		return nil, err
	}

	// Get refs (branches and tags)
	refs, err := getRefs(workDir, localOnly)
	if err != nil {
		return nil, err
	}

	// Parse and assign refs to commits
	err = assignRefs(commits, commitMap, refs)
	if err != nil {
		return nil, err
	}

	return &GitData{
		Commits:   commits,
		CommitMap: commitMap,
	}, nil
}

func parseGitLog(output string) ([]*CommitData, map[string]int, error) {
	var commits []*CommitData
	commitMap := make(map[string]int)

	lines := strings.Split(output, "\n")
	i := 0
	for i < len(lines) {
		line := lines[i]
		if !strings.HasPrefix(line, "COMMIT:") {
			i++
			continue
		}

		hash := strings.TrimPrefix(line, "COMMIT:")
		i++

		if i >= len(lines) {
			break
		}

		// Parse parents
		parentStr := lines[i]
		i++
		var parents []string
		if parentStr != "" {
			parents = strings.Fields(parentStr)
		}

		// Author name
		authorName := ""
		if i < len(lines) {
			authorName = lines[i]
			i++
		}

		// Author email
		authorEmail := ""
		if i < len(lines) {
			authorEmail = lines[i]
			i++
		}

		// Author date (ISO format)
		var authorDate time.Time
		if i < len(lines) {
			authorDate, _ = time.Parse(time.RFC3339, lines[i])
			i++
		}

		// Committer name
		committerName := ""
		if i < len(lines) {
			committerName = lines[i]
			i++
		}

		// Committer email
		committerEmail := ""
		if i < len(lines) {
			committerEmail = lines[i]
			i++
		}

		// Committer date
		var committerDate time.Time
		if i < len(lines) {
			committerDate, _ = time.Parse(time.RFC3339, lines[i])
			i++
		}

		// Subject
		subject := ""
		if i < len(lines) {
			subject = lines[i]
			i++
		}

		// Body (multiline, until ENDBODY)
		var bodyLines []string
		for i < len(lines) && lines[i] != "ENDBODY" {
			bodyLines = append(bodyLines, lines[i])
			i++
		}
		if i < len(lines) {
			i++ // skip ENDBODY
		}

		// Trim trailing empty lines from body
		for len(bodyLines) > 0 && bodyLines[len(bodyLines)-1] == "" {
			bodyLines = bodyLines[:len(bodyLines)-1]
		}

		body := strings.Join(bodyLines, "\n")

		commit := &CommitData{
			Hash:           hash,
			Parents:        parents,
			AuthorName:     authorName,
			AuthorEmail:    authorEmail,
			AuthorDate:     authorDate,
			CommitterName:  committerName,
			CommitterEmail: committerEmail,
			CommitterDate:  committerDate,
			Subject:        subject,
			Body:           body,
		}

		commitMap[hash] = len(commits)
		commits = append(commits, commit)
	}

	return commits, commitMap, nil
}

// RefEntry holds a reference name and its target hash
type RefEntry struct {
	Name   string
	Hash   string
	IsHead bool
	HeadTarget string // for HEAD -> branch
}

func getRefs(workDir string, localOnly bool) ([]RefEntry, error) {
	// Get HEAD
	headCmd := exec.Command("git", "-C", workDir, "symbolic-ref", "--short", "HEAD")
	headOut, headErr := headCmd.Output()
	headBranch := strings.TrimSpace(string(headOut))

	// Get HEAD hash
	headHashCmd := exec.Command("git", "-C", workDir, "rev-parse", "HEAD")
	headHashOut, _ := headHashCmd.Output()
	headHash := strings.TrimSpace(string(headHashOut))

	var refs []RefEntry

	// Add HEAD ref
	if headErr == nil && headBranch != "" && headHash != "" {
		refs = append(refs, RefEntry{
			Name:       "HEAD",
			Hash:       headHash,
			IsHead:     true,
			HeadTarget: headBranch,
		})
	}

	// Get all branches
	branchArgs := []string{"-C", workDir, "branch", "--format=%(refname:short) %(objectname)"}
	if !localOnly {
		branchArgs = []string{"-C", workDir, "branch", "-a", "--format=%(refname:short) %(objectname)"}
	}
	branchCmd := exec.Command("git", branchArgs...)
	branchOut, err := branchCmd.Output()
	if err == nil {
		for _, line := range strings.Split(strings.TrimSpace(string(branchOut)), "\n") {
			if line == "" {
				continue
			}
			parts := strings.SplitN(line, " ", 2)
			if len(parts) != 2 {
				continue
			}
			name, hash := parts[0], parts[1]
			// Skip remotes/HEAD
			if strings.HasSuffix(name, "/HEAD") {
				continue
			}
			refs = append(refs, RefEntry{Name: name, Hash: hash})
		}
	}

	// Get all tags
	tagCmd := exec.Command("git", "-C", workDir, "tag", "--format=%(refname:short) %(objectname:short) %(*objectname)")
	tagOut, err := tagCmd.Output()
	if err == nil {
		for _, line := range strings.Split(strings.TrimSpace(string(tagOut)), "\n") {
			if line == "" {
				continue
			}
			parts := strings.Fields(line)
			if len(parts) < 2 {
				continue
			}
			name := parts[0]
			hash := parts[1]
			// For annotated tags, use the dereferenced hash (commit hash)
			if len(parts) >= 3 && parts[2] != "" {
				hash = parts[2]
			} else {
				// Dereference to get commit hash
				derefCmd := exec.Command("git", "-C", workDir, "rev-parse", name+"^{commit}")
				derefOut, err := derefCmd.Output()
				if err == nil {
					hash = strings.TrimSpace(string(derefOut))
				}
			}
			refs = append(refs, RefEntry{Name: "tags/" + name, Hash: hash})
		}
	}

	return refs, nil
}

// assignRefs assigns ref information to commits
func assignRefs(commits []*CommitData, commitMap map[string]int, refs []RefEntry) error {
	// Build ref assignments
	type refAssign struct {
		name    string
		isTag   bool
		isRemote bool
		isHEAD  bool
		headTarget string
	}

	// Map from hash prefix to refs
	hashToRefs := make(map[string][]refAssign)

	for _, ref := range refs {
		if ref.IsHead {
			// Find the full hash in commits
			for _, c := range commits {
				if c.Hash == ref.Hash {
					hashToRefs[c.Hash] = append(hashToRefs[c.Hash], refAssign{
						name:       ref.HeadTarget,
						isHEAD:     true,
						headTarget: ref.HeadTarget,
					})
					break
				}
			}
			continue
		}

		isTag := strings.HasPrefix(ref.Name, "tags/")
		isRemote := !isTag && strings.Contains(ref.Name, "/")

		// Find matching commit (use full hash match, falling back to prefix match)
		matched := false
		for _, c := range commits {
			if strings.HasPrefix(c.Hash, ref.Hash) || c.Hash == ref.Hash {
				hashToRefs[c.Hash] = append(hashToRefs[c.Hash], refAssign{
					name:     ref.Name,
					isTag:    isTag,
					isRemote: isRemote,
				})
				matched = true
				break
			}
		}
		_ = matched
	}

	// Assign refs to commits
	for hash, assigns := range hashToRefs {
		idx, ok := commitMap[hash]
		if !ok {
			continue
		}
		commit := commits[idx]
		for _, a := range assigns {
			commit.Refs = append(commit.Refs, RefInfo{
				Name:       a.name,
				IsRemote:   a.isRemote,
				IsTag:      a.isTag,
				IsHEAD:     a.isHEAD,
				HeadTarget: a.headTarget,
			})
		}
	}

	return nil
}
