// parseModelFile parses a TOML model file
func parseModelFile(name, path string) (*BranchingModel, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	model := &BranchingModel{Name: name}

	// Simple TOML parser for our specific format
	content := string(data)
	parseModelContent(model, content)

	return model, nil
}

func parseModelContent(model *BranchingModel, content string) {
	lines := strings.Split(content, "\n")

	section := ""
	colorSection := "" // "terminal" or "svg"
	inMatches := false
	inMatchEntry := false
	matchPattern := ""
	var matchColors []string
	inUnknown := false
	var unknownList []string

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Section headers
		if trimmed == "[terminal_colors]" {
			section = "terminal_colors"
			colorSection = "terminal"
			inMatches = false
			inMatchEntry = false
			inUnknown = false
			continue
		}
		if trimmed == "[svg_colors]" {
			section = "svg_colors"
			colorSection = "svg"
			inMatches = false
			inMatchEntry = false
			inUnknown = false
			continue
		}

		if section == "" {
			// Top-level
			if strings.HasPrefix(trimmed, "persistence") {
				// Parse persistence array
				model.Persistence = parseRegexArray(lines, i)
			} else if strings.HasPrefix(trimmed, "order") {
				// Parse order array
				model.Order = parseRegexArray(lines, i)
			}
			continue
		}

		// In a color section
		if trimmed == "matches = [" {
			inMatches = true
			continue
		}
		if inMatches {
			if trimmed == "[" {
				// Start of a match entry
				inMatchEntry = true
				matchPattern = ""
				matchColors = nil
				continue
			}
			if inMatchEntry {
				if strings.HasPrefix(trimmed, "'") || strings.HasPrefix(trimmed, "\"") || strings.HasPrefix(trimmed, "^") {
					// This could be the pattern or a color
					val := extractStringValue(trimmed)
					if matchPattern == "" {
						matchPattern = val
					}
					continue
				}
				if trimmed == "[" {
					// Start of color list
					// Colors follow
					matchColors = parseStringArray(lines, i)
					continue
				}
				if trimmed == "]," || trimmed == "]" {
					// End of match entry
					if matchPattern != "" {
						re, err := regexp.Compile(matchPattern)
						if err == nil {
							cm := ColorMatch{Pattern: re, Colors: matchColors}
							if colorSection == "terminal" {
								model.TerminalColors.Matches = append(model.TerminalColors.Matches, cm)
							} else {
								model.SVGColors.Matches = append(model.SVGColors.Matches, cm)
							}
						}
					}
					inMatchEntry = false
					matchPattern = ""
					matchColors = nil
					continue
				}
				// Skip nested arrays (colors)
				if strings.HasPrefix(trimmed, "[") {
					// Parse inline array
					matchColors = parseInlineStringArray(trimmed)
					continue
				}
			}
			if trimmed == "]" {
				inMatches = false
				continue
			}
		}

		if strings.HasPrefix(trimmed, "unknown") {
			// Parse unknown colors
			inUnknown = true
			arr := parseUnknownColors(trimmed)
			if len(arr) > 0 {
				if colorSection == "terminal" {
					model.TerminalColors.Unknown = arr
				} else {
					model.SVGColors.Unknown = arr
				}
			}
			_ = inUnknown
			continue
		}
	}

	_ = inUnknown
	_ = unknownList
}

func extractStringValue(s string) string {
	s = strings.TrimSpace(s)
	s = strings.TrimSuffix(s, ",")
	s = strings.TrimSuffix(s, ",")
	if strings.HasPrefix(s, "'") {
		return strings.Trim(s, "'")
	}
	if strings.HasPrefix(s, "\"") {
		return strings.Trim(s, "\"")
	}
	return s
}

func parseRegexArray(lines []string, startIdx int) []*regexp.Regexp {
	var result []*regexp.Regexp
	line := strings.TrimSpace(lines[startIdx])

	// Check if it's inline: persistence = ["a", "b"]
	eqIdx := strings.Index(line, "=")
	if eqIdx < 0 {
		return result
	}
	rest := strings.TrimSpace(line[eqIdx+1:])

	if strings.HasPrefix(rest, "[") {
		// Could be multiline
		if strings.Contains(rest, "]") {
			// Inline array
			return parseRegexInlineArray(rest)
		}
		// Multiline
		for i := startIdx + 1; i < len(lines); i++ {
			l := strings.TrimSpace(lines[i])
			if l == "]" {
				break
			}
			if l == "" || strings.HasPrefix(l, "#") {
				continue
			}
			val := extractStringValue(l)
			if val != "" {
				re, err := regexp.Compile(val)
				if err == nil {
					result = append(result, re)
				}
			}
		}
	}
	return result
}

func parseRegexInlineArray(s string) []*regexp.Regexp {
	var result []*regexp.Regexp
	// Remove [ and ]
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "[")
	s = strings.TrimSuffix(s, "]")
	// Split by comma (simple approach)
	for _, part := range splitByComma(s) {
		val := extractStringValue(strings.TrimSpace(part))
		if val != "" {
			re, err := regexp.Compile(val)
			if err == nil {
				result = append(result, re)
			}
		}
	}
	return result
}

func parseStringArray(lines []string, startIdx int) []string {
	var result []string
	line := strings.TrimSpace(lines[startIdx])
	if strings.HasPrefix(line, "[") && strings.Contains(line, "]") {
		return parseInlineStringArray(line)
	}
	for i := startIdx + 1; i < len(lines); i++ {
		l := strings.TrimSpace(lines[i])
		if l == "]" || l == "]," {
			break
		}
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		val := extractStringValue(l)
		if val != "" {
			result = append(result, val)
		}
	}
	return result
}

func parseInlineStringArray(s string) []string {
	var result []string
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "[")
	s = strings.TrimSuffix(s, "]")
	s = strings.TrimSuffix(s, ",")
	for _, part := range splitByComma(s) {
		val := extractStringValue(strings.TrimSpace(part))
		if val != "" {
			result = append(result, val)
		}
	}
	return result
}

func parseUnknownColors(line string) []string {
	eqIdx := strings.Index(line, "=")
	if eqIdx < 0 {
		return nil
	}
	rest := strings.TrimSpace(line[eqIdx+1:])
	if strings.HasPrefix(rest, "[") {
		return parseInlineStringArray(rest)
	}
	// Single value
	val := extractStringValue(rest)
	if val != "" {
		return []string{val}
	}
	return nil
}

func splitByComma(s string) []string {
	var result []string
	depth := 0
	start := 0
	for i, c := range s {
		switch c {
		case '[':
			depth++
		case ']':
			depth--
		case ',':
			if depth == 0 {
				result = append(result, s[start:i])
				start = i + 1
			}
		}
	}
	if start < len(s) {
		result = append(result, s[start:])
	}
	return result
}

// GetBranchColor returns the terminal color for a branch name
func (m *BranchingModel) GetTerminalColor(branchName string, index int) string {
	for _, cm := range m.TerminalColors.Matches {
		if cm.Pattern.MatchString(branchName) {
			if len(cm.Colors) == 0 {
				break
			}
			return cm.Colors[index%len(cm.Colors)]
		}
	}
	if len(m.TerminalColors.Unknown) > 0 {
		return m.TerminalColors.Unknown[index%len(m.TerminalColors.Unknown)]
	}
	return "white"
}

// GetSVGColor returns the SVG color for a branch name
func (m *BranchingModel) GetSVGColor(branchName string, index int) string {
	for _, cm := range m.SVGColors.Matches {
		if cm.Pattern.MatchString(branchName) {
			if len(cm.Colors) == 0 {
