	}
	return "gray"
}

// GetPersistenceOrder returns the persistence order index for a branch name
// Lower index = higher persistence (more persistent)
func (m *BranchingModel) GetPersistenceOrder(branchName string) int {
	for i, re := range m.Persistence {
		if re.MatchString(branchName) {
			return i
		}
	}
	return len(m.Persistence) // not in persistence list = least persistent
}

// GetOrderGroup returns the order group for a branch
func (m *BranchingModel) GetOrderGroup(branchName string) int {
	for i, re := range m.Order {
		if re.MatchString(branchName) {
			return i
		}
	}
	return len(m.Order) // not in order list = last group
}

// createDefaultModels ensures the default models exist in config directory
