	}

	modelsDir := filepath.Join(configDir, "models")
	if err := os.MkdirAll(modelsDir, 0755); err != nil {
		return err
	}

	models := map[string]string{
		"git-flow": gitFlowModel,
		"simple":   simpleModel,
