	}
	// Single value
	val := extractStringValue(rest)
	if val != "" {
		return []string{val}
	}
	return nil
}

func splitByComma(s string) []string {
	var result []string
	depth := 0
	start := 0
	for i, c := range s {
		switch c {
		case '[':
			depth++
		case ']':
			depth--
		case ',':
			if depth == 0 {
				result = append(result, s[start:i])
				start = i + 1
			}
		}
	}
	if start < len(s) {
		result = append(result, s[start:])
	}
	return result
}

// GetBranchColor returns the terminal color for a branch name
func (m *BranchingModel) GetTerminalColor(branchName string, index int) string {
	for _, cm := range m.TerminalColors.Matches {
		if cm.Pattern.MatchString(branchName) {
			if len(cm.Colors) == 0 {
				break
			}
			return cm.Colors[index%len(cm.Colors)]
		}
	}
	if len(m.TerminalColors.Unknown) > 0 {
		return m.TerminalColors.Unknown[index%len(m.TerminalColors.Unknown)]
	}
	return "white"
}

// GetSVGColor returns the SVG color for a branch name
func (m *BranchingModel) GetSVGColor(branchName string, index int) string {
	for _, cm := range m.SVGColors.Matches {
		if cm.Pattern.MatchString(branchName) {
			if len(cm.Colors) == 0 {
				break
			}
			return cm.Colors[index%len(cm.Colors)]
		}
	}
	if len(m.SVGColors.Unknown) > 0 {
		return m.SVGColors.Unknown[index%len(m.SVGColors.Unknown)]
	}
	return "gray"
}

// GetPersistenceOrder returns the persistence order index for a branch name
// Lower index = higher persistence (more persistent)
func (m *BranchingModel) GetPersistenceOrder(branchName string) int {
	for i, re := range m.Persistence {
		if re.MatchString(branchName) {
			return i
		}
	}
	return len(m.Persistence) // not in persistence list = least persistent
}

// GetOrderGroup returns the order group for a branch
func (m *BranchingModel) GetOrderGroup(branchName string) int {
	for i, re := range m.Order {
		if re.MatchString(branchName) {
			return i
		}
	}
	return len(m.Order) // not in order list = last group
}

// createDefaultModels ensures the default models exist in config directory
func createDefaultModels() error {
	configDir, err := getConfigDir()
	if err != nil {
		return err
	}

	modelsDir := filepath.Join(configDir, "models")
	if err := os.MkdirAll(modelsDir, 0755); err != nil {
		return err
	}

	models := map[string]string{
		"git-flow": gitFlowModel,
		"simple":   simpleModel,
		"none":     noneModel,
	}

	for name, content := range models {
		path := filepath.Join(modelsDir, name+".toml")
		if _, err := os.Stat(path); os.IsNotExist(err) {
			if err := os.WriteFile(path, []byte(content), 0644); err != nil {
				return err
			}
		}
	}
	return nil
}

