package gitgraph

import (
	"sort"
)

// Branch represents a branch in the git graph
type Branch struct {
	Name        string   // Branch name (or "unknown" for pseudo-branches)
	HeadHash    string   // The commit hash at branch head
	Commits     []int    // List of commit indices (in order)
	Column      int      // Column in the display (-1 = unassigned)
	Color       string   // Terminal color
	SVGColor    string   // SVG color
	ColorIndex  int      // Which color index to use (for multi-color branches)
	IsPseudo    bool     // Is this a pseudo-branch (unnamed)?
	OrderGroup  int      // Order group from model
	PersistIdx  int      // Persistence index from model
	Range       [2]int   // Start and end commit indices in the global list (inclusive)
	SourceCol   int      // Source column (-1 = none)
	TargetCol   int      // Target column (-1 = none)
}

// Graph represents the complete visualization graph
type Graph struct {
	Commits      []*CommitData
	Branches     []*Branch
	CommitBranch []int     // For each commit, which branch index it belongs to
	CommitCol    []int     // For each commit, which column it is in
	NumCols      int       // Total number of columns
}

// buildGraph builds the graph from git data
func buildGraph(data *GitData, model *BranchingModel, sparse bool, reverse bool) (*Graph, error) {
	commits := data.Commits

	// Step 1: Find all branch heads
	branches := findBranches(commits, data.CommitMap, model)

	// Step 2: Assign commits to branches
	commitBranch := make([]int, len(commits))
	for i := range commitBranch {
		commitBranch[i] = -1 // unassigned
	}

	assignCommitsToBranches(commits, data.CommitMap, branches, commitBranch)

	// Step 3: Assign columns to branches
	numCols := assignColumns(branches)

	// Step 4: Build commit column mapping
	commitCol := make([]int, len(commits))
	for i, b := range commitBranch {
		if b >= 0 && b < len(branches) {
			commitCol[i] = branches[b].Column
		} else {
			commitCol[i] = -1
		}
	}

	// Step 5: Assign colors
	assignColors(branches, model)

	g := &Graph{
		Commits:      commits,
		Branches:     branches,
		CommitBranch: commitBranch,
		CommitCol:    commitCol,
		NumCols:      numCols,
	}

	return g, nil
}

// findBranches finds all branch candidates from the commit data
func findBranches(commits []*CommitData, commitMap map[string]int, model *BranchingModel) []*Branch {
	var branches []*Branch
	branchByName := make(map[string]*Branch)

	// Collect all refs to find branch heads
	for _, c := range commits {
		for _, ref := range c.Refs {
			if ref.IsTag {
				// Tags go into separate category
				name := ref.Name
				if b, exists := branchByName[name]; !exists {
					b = &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99, // unassigned initially
					}
					branches = append(branches, b)
					branchByName[name] = b
				} else {
					_ = b
				}
			} else if !ref.IsHEAD {
				// Regular branch
				name := ref.Name
				if _, exists := branchByName[name]; !exists {
					b := &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99,
					}
					branches = append(branches, b)
					branchByName[name] = b
				}
			}
		}
	}

	// Sort branches by persistence (more persistent = higher priority)
	sort.SliceStable(branches, func(i, j int) bool {
		pi := model.GetPersistenceOrder(branches[i].Name)
		pj := model.GetPersistenceOrder(branches[j].Name)
		if pi != pj {
			return pi < pj
		}
		// Same persistence: sort alphabetically for stability
		return branches[i].Name < branches[j].Name
	})

	// Set persistence indices
	for i, b := range branches {
		b.PersistIdx = i
		b.OrderGroup = model.GetOrderGroup(b.Name)
	}

	return branches
}

// assignCommitsToBranches assigns each commit to a branch
func assignCommitsToBranches(commits []*CommitData, commitMap map[string]int, branches []*Branch, commitBranch []int) {
	// Track which commits are assigned
	assigned := make([]bool, len(commits))

	// Process each branch in persistence order
	for bi, branch := range branches {
		// Skip tag branches
		if isTagBranch(branch.Name) {
			continue
		}

		// Find the branch head commit
		headIdx := -1
		for ci, c := range commits {
			if c.Hash == branch.HeadHash {
				headIdx = ci
				break
			}
		}

		if headIdx < 0 {
			continue
		}

		// Trace from head following primary parents
		var branchCommits []int
		idx := headIdx
		for idx >= 0 && idx < len(commits) && !assigned[idx] {
			branchCommits = append(branchCommits, idx)
			assigned[idx] = true
			commitBranch[idx] = bi

			// Follow primary parent
			c := commits[idx]
			if len(c.Parents) == 0 {
				break
			}
			parentHash := c.Parents[0]
			nextIdx, ok := commitMap[parentHash]
			if !ok {
				break
			}
			idx = nextIdx
		}

		branch.Commits = branchCommits
		if len(branchCommits) > 0 {
			branch.Range = [2]int{branchCommits[0], branchCommits[len(branchCommits)-1]}
		}
	}

	// Handle unassigned commits (secondary parents of merge commits)
	// Create pseudo-branches for them
	pseudoCount := 0
	changed := true
	for changed {
		changed = false
		for ci, c := range commits {
			if assigned[ci] {
				continue
			}

			// This commit is unassigned. Find which branch is "expecting" it
			// by looking at merge commits that reference it as secondary parent
			// For now, find ANY assigned commit that has this commit as a parent
			for _, oc := range commits {
				if !isAssigned(oc.Hash, commitMap, assigned) {
					continue
				}
				for pi, ph := range oc.Parents {
					if pi == 0 {
						continue // Skip primary parent
					}
					if ph == c.Hash {
						// Create a pseudo branch for this unassigned chain
						pseudoName := "unknown"
						_ = pseudoName
						pseudoBranch := createPseudoBranch(commits, commitMap, ci, assigned, commitBranch, pseudoCount)
						if pseudoBranch != nil {
							branches = append(branches, pseudoBranch)
							bi := len(branches) - 1
							for _, pci := range pseudoBranch.Commits {
								commitBranch[pci] = bi
								assigned[pci] = true
							}
							pseudoCount++
							changed = true
						}
						goto nextCommit
					}
				}
			}
			nextCommit:
		}
	}

	_ = pseudoCount
}

func isTagBranch(name string) bool {
	return len(name) >= 5 && name[:5] == "tags/"
}

func isAssigned(hash string, commitMap map[string]int, assigned []bool) bool {
	idx, ok := commitMap[hash]
	if !ok {
		return false
	}
	return assigned[idx]
}

func createPseudoBranch(commits []*CommitData, commitMap map[string]int, startIdx int, assigned []bool, commitBranch []int, pseudoCount int) *Branch {
	var branchCommits []int
	idx := startIdx

	for idx >= 0 && idx < len(commits) && !assigned[idx] {
		branchCommits = append(branchCommits, idx)

		c := commits[idx]
		if len(c.Parents) == 0 {
			break
		}
		parentHash := c.Parents[0]
		nextIdx, ok := commitMap[parentHash]
		if !ok {
			break
		}
		idx = nextIdx
	}

	if len(branchCommits) == 0 {
		return nil
	}

	return &Branch{
		Name:      "unknown",
		HeadHash:  commits[startIdx].Hash,
		Commits:   branchCommits,
		IsPseudo:  true,
		Column:    99,
		Range:     [2]int{branchCommits[0], branchCommits[len(branchCommits)-1]},
	}
}

// assignColumns assigns column numbers to branches
func assignColumns(branches []*Branch) int {
	// Branches with no commits get col 99
	// Other branches get columns based on their ranges

	// Sort branches for column assignment
	// Priority: order group, then length (shorter first), then start position
	type branchSort struct {
		idx   int
		start int
		end   int
		length int
		orderGroup int
	}

	var toSort []branchSort
	for i, b := range branches {
		if b.Range[0] == 0 && b.Range[1] == 0 && len(b.Commits) == 0 {
			b.Column = 99
			continue
		}
		if len(b.Commits) == 0 {
			b.Column = 99
			continue
		}
		toSort = append(toSort, branchSort{
			idx:   i,
			start: b.Range[0],
			end:   b.Range[1],
			length: b.Range[1] - b.Range[0],
			orderGroup: b.OrderGroup,
		})
	}

	// Sort: first by order group, then by length (ascending), then by start (ascending)
	sort.SliceStable(toSort, func(i, j int) bool {
		a, b2 := toSort[i], toSort[j]
		if a.orderGroup != b2.orderGroup {
			return a.orderGroup < b2.orderGroup
		}
		if a.length != b2.length {
			return a.length < b2.length
		}
		return a.start < b2.start
	})

	// Assign columns using a greedy interval scheduling approach
	// Each column can hold one branch range at a time (no overlap)
	// Actually: we need to find minimum columns such that no two active branches share a column

	// Use an "occupied" array: for each column, what's the last end row
	occupied := []int{} // last end row for each column

	for _, bs := range toSort {
		b := branches[bs.idx]

		// Find the earliest column where [bs.start, bs.end] doesn't overlap
		col := -1
		for c, lastEnd := range occupied {
			if bs.start > lastEnd {
				col = c
				break
			}
		}

		if col == -1 {
			// Need a new column
			col = len(occupied)
			occupied = append(occupied, bs.end)
		} else {
			occupied[col] = bs.end
		}

		b.Column = col
	}

	numCols := len(occupied)
	if numCols == 0 {
		numCols = 1
	}
	return numCols
}

// assignColors assigns terminal and SVG colors to branches
func assignColors(branches []*Branch, model *BranchingModel) {
	// Count how many times each pattern has been matched for alternating colors
	patternCount := make(map[string]int)

	for _, b := range branches {
		colorKey := b.Name

		// Find the matching pattern for color key
		for _, cm := range model.TerminalColors.Matches {
			if cm.Pattern.MatchString(b.Name) {
				colorKey = cm.Pattern.String()
				break
			}
		}

		count := patternCount[colorKey]
		patternCount[colorKey] = count + 1

		b.Color = model.GetTerminalColor(b.Name, count)
		b.SVGColor = model.GetSVGColor(b.Name, count)
		b.ColorIndex = count
	}
}
