	// Sort: first by order group, then by length (ascending), then by start (ascending)
	sort.SliceStable(toSort, func(i, j int) bool {
		a, b2 := toSort[i], toSort[j]
		if a.orderGroup != b2.orderGroup {
			return a.orderGroup < b2.orderGroup
		}
		if a.length != b2.length {
			return a.length < b2.length
		}
		return a.start < b2.start
	})

	// Assign columns using a greedy interval scheduling approach
	// Each column can hold one branch range at a time (no overlap)
	// Actually: we need to find minimum columns such that no two active branches share a column

	// Use an "occupied" array: for each column, what's the last end row
