		b := branches[bs.idx]

		// Find the earliest column where [bs.start, bs.end] doesn't overlap
		col := -1
		for c, lastEnd := range occupied {
			if bs.start > lastEnd {
				col = c
				break
			}
		}

		if col == -1 {
			// Need a new column
			col = len(occupied)
			occupied = append(occupied, bs.end)
		} else {
			occupied[col] = bs.end
		}

		b.Column = col
	}

	numCols := len(occupied)
	if numCols == 0 {
		numCols = 1
	}
	return numCols
}

// assignColors assigns terminal and SVG colors to branches
func assignColors(branches []*Branch, model *BranchingModel) {
	// Count how many times each pattern has been matched for alternating colors
	patternCount := make(map[string]int)

	for _, b := range branches {
		colorKey := b.Name

		// Find the matching pattern for color key
		for _, cm := range model.TerminalColors.Matches {
			if cm.Pattern.MatchString(b.Name) {
				colorKey = cm.Pattern.String()
				break
			}
		}

		count := patternCount[colorKey]
		patternCount[colorKey] = count + 1

		b.Color = model.GetTerminalColor(b.Name, count)
		b.SVGColor = model.GetSVGColor(b.Name, count)
		b.ColorIndex = count
	}
}
