		var mergeSpawns []SpawnInfo
		if c != nil && len(c.Parents) > 1 {
			if spawns, ok := spawnAt[idx]; ok {
				// Only include spawns that are actual secondary parents of THIS commit
				for _, s := range spawns {
					if s.BranchIdx >= 0 && s.BranchIdx < len(g.Branches) {
						mergeSpawns = append(mergeSpawns, s)
					}
				}
			}
		}

		// Build graph prefix for this commit
		prefix := buildCommitPrefix(commitCol, activeAt, mergeSpawns, numCols, style, useColor, g.Branches, g.CommitBranch[idx])

		// Format commit text
		text := formatCommit(c, format, useColor, g.CommitBranch[idx], g.Branches, model)

		// Write the commit row
		writeRow(w, prefix, graphWidth, text, format, wrap, termWidth, style, activeAt, numCols, useColor, g, idx)

		// Check if connector row needed after this commit
		// A connector appears if some branch ends at this commit index
		connectors := findConnectors(g, idx)
		if len(connectors) > 0 {
			// Generate connector row(s)
			writeConnectorRows(w, connectors, activeAt, numCols, style, useColor, g)
		}
	}

	return nil
}

// getActiveColumns returns which columns are active at commit index idx
func getActiveColumns(g *Graph, idx int, numCols int) []bool {
	active := make([]bool, numCols)
	for _, b := range g.Branches {
		if b.Column >= 0 && b.Column < numCols {
			if b.SpawnIdx <= idx && idx <= b.Range[1] {
				active[b.Column] = true
			}
		}
	}
	return active
}

// Connector represents a branch ending and connecting to its target
type Connector struct {
	SrcCol    int // Column of the ending branch
	DstCol    int // Column of the target
	SrcBranch int // Branch index
}

func findConnectors(g *Graph, idx int) []Connector {
	var connectors []Connector
	for bi, b := range g.Branches {
		if b.Column < 0 || b.Column >= g.NumCols {
			continue
		}
		if b.Range[1] != idx {
			continue
		}
		// Branch ends here. Find the primary parent's column.
		if len(b.Commits) == 0 {
			continue
		}
		lastCommitIdx := b.Range[1]
		lastCommit := g.Commits[lastCommitIdx]
		if len(lastCommit.Parents) == 0 {
			continue
		}
		primaryParentHash := lastCommit.Parents[0]
		parentIdx, ok := g.CommitMap[primaryParentHash]
		if !ok {
			continue
		}
		parentBranchIdx := g.CommitBranch[parentIdx]
		if parentBranchIdx < 0 {
			continue
		}
		dstCol := g.Branches[parentBranchIdx].Column
		if dstCol == b.Column {
			continue // Same column, no connector needed
		}
		connectors = append(connectors, Connector{
			SrcCol:    b.Column,
			DstCol:    dstCol,
			SrcBranch: bi,
		})
	}
	return connectors
}

// buildCommitPrefix builds the graph prefix for a commit row
func buildCommitPrefix(commitCol int, active []bool, spawns []SpawnInfo, numCols int, style StyleChars, useColor bool, branches []*Branch, branchIdx int) string {
	// Build a grid: for each column, what char to show and what connector to show
	// grid[col] = (nodeChar, connectorChar)
	type cell struct {
		node  string
		right string
	}

	grid := make([]cell, numCols)

	// Initialize all columns
	for i := 0; i < numCols; i++ {
		if active[i] {
			grid[i].node = style.Vertical
		} else {
			grid[i].node = " "
		}
		grid[i].right = " "
	}

	// Set the commit column
	if commitCol >= 0 && commitCol < numCols {
		isMerge := false
		if branchIdx >= 0 && branchIdx < len(branches) {
			_ = isMerge
		}
		// We'll set this based on actual commit data
		grid[commitCol].node = style.Commit
	}

	// Handle merge spawns (non-sparse mode)
	// spawns are the branches that start FROM this merge commit
	if len(spawns) > 0 && commitCol >= 0 {
		// This is a merge commit. Set the merge commit symbol.
		grid[commitCol].node = style.MergeCommit

		// For each spawn, determine if it's to the right or left
		for _, s := range spawns {
			if s.Column > commitCol {
				// Spawn is to the right
				// Put '<' arrow on the commit column going right
				// Then horizontal lines until the spawn column
				// Then '┐' at the spawn column
				grid[commitCol].right = style.MergeRight
				for col := commitCol + 1; col < s.Column; col++ {
					grid[col].node = style.Horizontal
					grid[col].right = style.Horizontal
				}
				grid[s.Column].node = style.TopRight // ┐
				grid[s.Column].right = " "
			} else if s.Column < commitCol {
				// Spawn is to the left
				grid[commitCol].right = style.MergeLeft
				for col := s.Column + 1; col < commitCol; col++ {
					grid[col].node = style.Horizontal
					grid[col].right = style.Horizontal
				}
				grid[s.Column].node = style.TopLeft // ┌
			}
		}
	}

	// Build the string
	var sb strings.Builder
	sb.WriteString(" ") // Leading space
	for _, c := range grid {
		sb.WriteString(c.node)
		sb.WriteString(c.right)
	}

	return sb.String()
}

func writeRow(w io.Writer, prefix string, graphWidth int, text string, format *CommitFormat, wrap *WrapConfig, termWidth int, style StyleChars, active []bool, numCols int, useColor bool, g *Graph, idx int) {
	prefixWidth := graphWidth // This is the visual width of the prefix

	if format.Kind == FormatOneline || format.Kind == "custom" {
		// Single line
		if text == "" {
			fmt.Fprintln(w, prefix)
		} else {
			// Pad prefix to graphWidth
			paddedPrefix := padTo(prefix, graphWidth)
			// Write the text
			if wrap != nil && wrap.Width == -1 {
				// No wrap
				fmt.Fprintln(w, paddedPrefix+text)
			} else if termWidth > 0 && wrap != nil && wrap.Width >= 0 {
				// Wrap
				wrapped := wrapText(text, termWidth-prefixWidth, wrap.Indent1, wrap.Indent2, prefixWidth)
				lines := strings.Split(wrapped, "\n")
				for i, line := range lines {
					if i == 0 {
						fmt.Fprintln(w, paddedPrefix+line)
					} else {
						continuationPrefix := buildContinuationPrefix(active, numCols, style, useColor, g, idx)
						fmt.Fprintln(w, continuationPrefix+strings.Repeat(" ", wrap.Indent2)+line)
					}
				}
			} else {
				fmt.Fprintln(w, paddedPrefix+text)
			}
		}
		return
	}

	// Multi-line formats (short, medium, full)
	lines := strings.Split(text, "\n")

	for i, line := range lines {
		var linePrefix string
		if i == 0 {
			// First line: use the commit prefix
			linePrefix = padTo(prefix, graphWidth)
		} else {
			// Continuation lines: use the continuation prefix
			linePrefix = buildContinuationPrefix(active, numCols, style, useColor, g, idx)
		}
		fmt.Fprintln(w, linePrefix+line)
	}
}

func buildContinuationPrefix(active []bool, numCols int, style StyleChars, useColor bool, g *Graph, idx int) string {
	var sb strings.Builder
	sb.WriteString(" ")
	for i, a := range active {
		if i >= numCols {
			break
		}
		if a {
			sb.WriteString(style.Vertical)
		} else {
			sb.WriteString(" ")
		}
		sb.WriteString(" ")
	}
	return sb.String()
}

func padTo(s string, width int) string {
	vis := visWidth(s)
	if vis >= width {
		return s
	}
	return s + strings.Repeat(" ", width-vis)
}

func visWidth(s string) int {
	// Count visual width (Unicode chars might be multi-byte but single-column)
	return utf8.RuneCountInString(s)
}

func writeConnectorRows(w io.Writer, connectors []Connector, activeAt []bool, numCols int, style StyleChars, useColor bool, g *Graph) {
	// Combine all connectors into one row
	// Sort connectors by destination (leftmost first)

	// The connector row spans from the leftmost target to the rightmost source
	// For each connector: draw a line from src to dst

	// Build the connector row
	type cell struct {
		node  string
		right string
	}
	grid := make([]cell, numCols)

	// Initialize: active columns get '│', inactive get ' '
	for i := 0; i < numCols; i++ {
		if activeAt[i] {
			grid[i].node = style.Vertical
			grid[i].right = " "
		} else {
			grid[i].node = " "
			grid[i].right = " "
		}
	}

	// Track which columns are 'ending' (will be removed after this connector)
	type connInfo struct {
		src int
		dst int
	}

	// Sort connectors by... leftmost first? 
	// Let's just apply them in order
	for _, conn := range connectors {
		src := conn.SrcCol
		dst := conn.DstCol

		if src > dst {
			// Connector goes left (src is to the right of dst)
			// Pattern: ├─...─┘ (dst has ├, src has ┘)
			// Set dst column
			if activeAt[dst] {
				grid[dst].node = style.LeftCross // ├
			} else {
				grid[dst].node = style.BotLeft // └
			}
			grid[dst].right = style.Horizontal
			// Fill horizontal
			for col := dst + 1; col < src; col++ {
				// Check if there's another connector going through here
				if grid[col].node == style.BotCross || grid[col].node == style.LeftCross {
					// already has a junction
				} else if grid[col].node == style.BotRight {
					// already ends here
				} else {
					grid[col].node = style.Horizontal
				}
				grid[col].right = style.Horizontal
			}
			// Set src column
			grid[src].node = style.BotRight // ┘
			grid[src].right = " "
		} else {
			// Connector goes right (src is to the left of dst)
			// Pattern: └─...─┐ (src has └, dst has ┐)
			if activeAt[src] {
				grid[src].node = style.BotLeft + style.Horizontal // ? 
			}
			_ = dst // not used for right connectors... let me rethink

			// Actually for '│ └─┐':
			// src=col1 (release), dst=col2 (develop spawning point)
			// col1 shows '└', col2 shows '┐'
			if activeAt[src] {
				grid[src].node = style.BotLeft // └ 
			} else {
				grid[src].node = style.BotLeft
			}
			grid[src].right = style.Horizontal
			for col := src + 1; col < dst; col++ {
				grid[col].node = style.Horizontal
				grid[col].right = style.Horizontal
			}
			grid[dst].node = style.TopRight // ┐
			grid[dst].right = " "
		}
	}

	// Build the string and trim trailing spaces
	var sb strings.Builder
	sb.WriteString(" ")
	lastNonSpace := 0
	chars := []string{}
	for _, c := range grid {
		chars = append(chars, c.node, c.right)
	}
	for i, ch := range chars {
		if ch != " " {
			lastNonSpace = i + 1
		}
	}
	for i := 0; i < lastNonSpace; i++ {
		sb.WriteString(chars[i])
	}

	fmt.Fprintln(w, sb.String())
}

func formatCommit(c *CommitData, format *CommitFormat, useColor bool, branchIdx int, branches []*Branch, model *BranchingModel) string {
	if c == nil {
		return ""
	}

	var branchColor string
	if branchIdx >= 0 && branchIdx < len(branches) {
		branchColor = branches[branchIdx].Color
	}

	switch format.Kind {
	case FormatOneline:
		return formatOnelineCommit(c, useColor, branchColor)
	case FormatShort:
		return formatShortCommit(c, useColor, branchColor)
	case FormatMedium:
		return formatMediumCommit(c, useColor, branchColor)
	case FormatFull:
		return formatFullCommit(c, useColor, branchColor)
	case "custom":
		return expandFormatString(format.Template, c, useColor, false)
	}
	return ""
}

func formatOnelineCommit(c *CommitData, useColor bool, branchColor string) string {
	var sb strings.Builder

	// Abbreviated hash
	abbr := c.Hash[:7]
	if useColor {
		sb.WriteString(colorize(abbr, "bright_yellow"))
	} else {
		sb.WriteString(abbr)
	}

	// Refs
	refsStr := formatRefsString(c, useColor, false)
	if refsStr != "" {
		sb.WriteString(" ")
		sb.WriteString(refsStr)
	}

	// Subject
	if c.Subject != "" {
		sb.WriteString(" ")
		sb.WriteString(c.Subject)
	}

	return sb.String()
}

func formatRefsString(c *CommitData, useColor bool, localOnly bool) string {
	var branches []string
	var tags []string

	// Find HEAD target
	headTarget := ""
	for _, r := range c.Refs {
		if r.IsHEAD {
			headTarget = r.HeadTarget
		}
	}

	headAdded := false
	for _, r := range c.Refs {
		if r.IsHEAD {
			continue
		}
		if r.IsTag {
			tags = append(tags, strings.TrimPrefix(r.Name, "tags/"))
		} else {
			if localOnly && r.IsRemote {
				continue
			}
			if r.Name == headTarget && !headAdded {
				if useColor {
					branches = append([]string{colorize("HEAD ->", "bright_cyan") + " " + colorize(r.Name, getBranchRefColor(r))}, branches...)
				} else {
					branches = append([]string{"HEAD -> " + r.Name}, branches...)
				}
				headAdded = true
			} else {
				if useColor {
					branches = append(branches, colorize(r.Name, getBranchRefColor(r)))
				} else {
					branches = append(branches, r.Name)
				}
			}
		}
	}

	if headTarget != "" && !headAdded {
		if useColor {
			branches = append([]string{colorize("HEAD ->", "bright_cyan") + " " + headTarget}, branches...)
		} else {
			branches = append([]string{"HEAD -> " + headTarget}, branches...)
		}
	}

	var result []string

	if len(branches) > 0 {
		branchStr := "(" + strings.Join(branches, ", ") + ")"
		result = append(result, branchStr)
	}

	for _, t := range tags {
		result = append(result, "["+t+"]")
	}

	return strings.Join(result, " ")
}

func getBranchRefColor(r RefInfo) string {
	if r.IsRemote {
		return "bright_red"
	}
	return "bright_cyan" // default
}

func formatShortCommit(c *CommitData, useColor bool, branchColor string) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsString(c, false, false)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	// Merge line for merge commits
	if len(c.Parents) > 1 {
		var abbrs []string
		for _, p := range c.Parents {
			if len(p) >= 7 {
				abbrs = append(abbrs, p[:7])
			}
		}
		sb.WriteString("\nMerge: " + strings.Join(abbrs, " "))
	}

	sb.WriteString("\nAuthor: " + c.AuthorName + " <" + c.AuthorEmail + ">")
	sb.WriteString("\n")
	sb.WriteString("\n    " + c.Subject)
	sb.WriteString("\n")

	return sb.String()
}

