// buildGraph builds the graph from git data
func buildGraph(data *GitData, model *BranchingModel, sparse bool, reverse bool) (*Graph, error) {
	commits := data.Commits

	// Step 1: Find all branch heads
	branches := findBranches(commits, data.CommitMap, model)

	// Step 2: Assign commits to branches
	commitBranch := make([]int, len(commits))
	for i := range commitBranch {
		commitBranch[i] = -1 // unassigned
	}

	assignCommitsToBranches(commits, data.CommitMap, branches, commitBranch, model)

	// Step 3: Assign columns to branches
	numCols := assignColumns(branches)

	// Step 4: Build commit column mapping
	commitCol := make([]int, len(commits))
	for i, b := range commitBranch {
		if b >= 0 && b < len(branches) {
			commitCol[i] = branches[b].Column
		} else {
			commitCol[i] = -1
		}
	}

	// Step 5: Assign colors
	assignColors(branches, model)

	g := &Graph{
		Commits:      commits,
		Branches:     branches,
		CommitBranch: commitBranch,
		CommitCol:    commitCol,
		NumCols:      numCols,
		CommitMap:    data.CommitMap,
	}

	return g, nil
}

// BranchHeadMap maps commit hash -> branch index (for all named branches)
type branchHeadMap struct {
	m map[string]int // commit hash -> branch index
}

func makeBranchHeadMap(branches []*Branch) branchHeadMap {
	m := make(map[string]int)
	for i, b := range branches {
		if !b.IsPseudo && b.HeadHash != "" {
			m[b.HeadHash] = i
		}
	}
	return branchHeadMap{m}
}

func (bm branchHeadMap) hasPersistentBranch(hash string, branches []*Branch, persistenceLen int) bool {
	bi, ok := bm.m[hash]
	if !ok {
		return false
	}
	b := branches[bi]
	// Returns true if this branch has a defined persistence (matches a pattern)
	return b.PersistIdx < persistenceLen
}

// findBranches finds all branch candidates from the commit data
func findBranches(commits []*CommitData, commitMap map[string]int, model *BranchingModel) []*Branch {
	var branches []*Branch
	branchByName := make(map[string]*Branch)

	// Collect all refs to find branch heads
	for _, c := range commits {
		for _, ref := range c.Refs {
			if ref.IsTag {
				// Tags go into separate category
				name := ref.Name
				if _, exists := branchByName[name]; !exists {
					b := &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99, // unassigned initially
						SpawnIdx: -1,
					}
					branches = append(branches, b)
					branchByName[name] = b
				}
			} else if !ref.IsHEAD {
				// Regular branch
				name := ref.Name
				if _, exists := branchByName[name]; !exists {
					b := &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99,
						SpawnIdx: -1,
					}
					branches = append(branches, b)
					branchByName[name] = b
				}
			}
		}
	}

	// Sort branches by persistence (more persistent = higher priority = lower index)
	sort.SliceStable(branches, func(i, j int) bool {
		pi := model.GetPersistenceOrder(branches[i].Name)
		pj := model.GetPersistenceOrder(branches[j].Name)
		if pi != pj {
			return pi < pj
		}
		// Same persistence: sort alphabetically for stability
		return branches[i].Name < branches[j].Name
	})

	// Set persistence indices and order groups
	for i, b := range branches {
		b.PersistIdx = model.GetPersistenceOrder(b.Name)
		b.OrderGroup = model.GetOrderGroup(b.Name)
		_ = i
	}

	return branches
}

// assignCommitsToBranches assigns each commit to a branch
func assignCommitsToBranches(commits []*CommitData, commitMap map[string]int, branches []*Branch, commitBranch []int, model *BranchingModel) {
	// Track which commits are assigned
	assigned := make([]bool, len(commits))

	// Build map of branch head -> branch index for all NAMED branches
	headToBranch := make(map[string]int)
	for bi, b := range branches {
		if !b.IsPseudo && b.HeadHash != "" {
			headToBranch[b.HeadHash] = bi
		}
	}

	persistenceLen := len(model.Persistence)

	// Process each branch in persistence order
	for bi, branch := range branches {
		if bi >= len(branches) {
			break
		}

		// Skip tag branches (no commits to assign)
		if isTagBranch(branch.Name) {
			continue
		}

		// Find the branch head commit
		headIdx := -1
		for ci, c := range commits {
			if c.Hash == branch.HeadHash {
				headIdx = ci
				break
			}
		}

		if headIdx < 0 {
			continue
		}

		if assigned[headIdx] {
			// Already taken (by a pseudo-branch)
			continue
		}

		// Trace from head following primary parents
