// renderSVG renders the graph as SVG
func renderSVG(g *Graph, model *BranchingModel, w io.Writer) error {
	const rowHeight = 15
	const colWidth = 15
	const nodeRadius = 4
	const margin = 15

	// Calculate dimensions
	numCommitRows := countCommitRows(g)
	height := numCommitRows*rowHeight + margin
	width := (g.NumCols+1)*colWidth

	fmt.Fprintf(w, "<svg height=\"%d\" viewBox=\"0 0 %d %d\" width=\"%d\" xmlns=\"http://www.w3.org/2000/svg\">\n",
		height, width, height, width)

	// Render SVG elements
	renderSVGElements(g, model, w, rowHeight, colWidth, nodeRadius, margin)

	fmt.Fprintln(w, "</svg>")
	return nil
}

func countCommitRows(g *Graph) int {
	return len(g.Commits)
}

func renderSVGElements(g *Graph, model *BranchingModel, w io.Writer, rowHeight, colWidth, nodeRadius, margin int) {
	// For each commit, draw:
	// 1. Vertical lines for the branch
	// 2. Bezier curves for spawns and merges
	// 3. Circles for the commit

	// Track 'next commit' in each column for line drawing
	type colState struct {
		nextCommitY int // Y coordinate of the next commit in this column
		color       string
	}
	_ = colState{}

	// Process commits in reverse order (from newest to oldest = top to bottom)
	// Actually process top-to-bottom (index 0 is newest)

	// Pre-compute column colors
	colColor := make(map[int]string)
	for _, b := range g.Branches {
		if b.Column >= 0 && b.Column < g.NumCols {
			if _, exists := colColor[b.Column]; !exists {
				colColor[b.Column] = b.SVGColor
			}
		}
	}

	// Build list of SVG elements to output (we need to order them correctly)
	// First: all lines, then all circles
	type svgLine struct {
		x1, y1, x2, y2 int
		color string
	}
	type svgPath struct {
		d string
		color string
	}
	type svgCircle struct {
		cx, cy int
		fill, stroke string
	}

	var lines []svgLine
	var paths []svgPath
	var circles []svgCircle

	// Process each commit
	for i, c := range g.Commits {
		if c == nil {
			continue
		}

		branchIdx := g.CommitBranch[i]
		if branchIdx < 0 || branchIdx >= len(g.Branches) {
			continue
		}
		b := g.Branches[branchIdx]

		col := b.Column
		if col < 0 || col >= g.NumCols {
