				pathStr := fmt.Sprintf("M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d",
					x, y, x, y, x, midY, midX, midY, destX, midY, destX, nextRowY, destX, destCommitY)
				paths = append(paths, svgPath{pathStr, spawnBranch.SVGColor})
			}
		}

		// Draw merge-back path: from last commit in this branch back to its primary parent
		if isLastInBranch && len(c.Parents) > 0 {
			primaryParentHash := c.Parents[0]
			parentIdx, ok := g.CommitMap[primaryParentHash]
			if !ok {
				goto noMergePath
			}
			parentBranchIdx := g.CommitBranch[parentIdx]
			if parentBranchIdx < 0 {
				goto noMergePath
			}
			destBranch := g.Branches[parentBranchIdx]
			destCol := destBranch.Column
			if destCol == col {
				goto noMergePath
			}

			{
				destX := (destCol+1) * colWidth
				destY := (parentIdx+1) * rowHeight

				// Draw line from this commit (y) down to one row before the destination
				// Then bezier to destination
				prevDestY := destY - rowHeight

				var pathStr string
				if prevDestY > y {
					// Straight line part
					midY := float64(prevDestY + destY) / 2.0
					midX := float64(x + destX) / 2.0
					pathStr = fmt.Sprintf("M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d",
						x, y, x, prevDestY, x, midY, midX, midY, destX, midY, destX, destY, destX, destY)
				} else {
					// No straight line part, just the bezier
					midY := float64(y + destY) / 2.0
					midX := float64(x + destX) / 2.0
					pathStr = fmt.Sprintf("M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d",
						x, y, x, y, x, midY, midX, midY, destX, midY, destX, destY, destX, destY)
				}
				paths = append(paths, svgPath{pathStr, color})
			}
		}
		noMergePath:

		circles = append(circles, svgCircle{x, y, circleFill, color})
	}

	// Write all lines first, then circles (so lines go behind circles)
	for _, l := range lines {
		fmt.Fprintf(w, "<line stroke=\"%s\" stroke-width=\"1\" x1=\"%d\" x2=\"%d\" y1=\"%d\" y2=\"%d\"/>\n",
			l.color, l.x1, l.x2, l.y1, l.y2)
	}

	for _, p := range paths {
		fmt.Fprintf(w, "<path d=\"%s\" fill=\"none\" stroke=\"%s\" stroke-width=\"1\"/>\n",
			p.d, p.color)
	}

	for _, c := range circles {
		fmt.Fprintf(w, "<circle cx=\"%d\" cy=\"%d\" fill=\"%s\" r=\"%d\" stroke=\"%s\" stroke-width=\"1\"/>\n",
			c.cx, c.cy, c.fill, nodeRadius, c.stroke)
	}
}
GOEOF

