package gitgraph

import (
	"sort"
)

// Branch represents a branch in the git graph
type Branch struct {
	Name        string // Branch name (or "unknown" for pseudo-branches)
	HeadHash    string // The commit hash at branch head
	Commits     []int  // List of commit indices (in order)
	Column      int    // Column in the display (-1 = unassigned)
	Color       string // Terminal color
	SVGColor    string // SVG color
	ColorIndex  int    // Which color index to use (for multi-color branches)
	IsPseudo    bool   // Is this a pseudo-branch (unnamed)?
	SpawnIdx    int    // Commit index where this branch visually starts (the merge commit that spawns it)
	OrderGroup  int    // Order group from model
	PersistIdx  int    // Persistence index from model
	Range       [2]int // Start and end commit indices in the global list (inclusive)
	SourceGroup int    // Source order group (for sorting)
	TargetGroup int    // Target order group (-1 = none)
}

// Graph represents the complete visualization graph
type Graph struct {
	Commits      []*CommitData
	Branches     []*Branch
	CommitBranch []int          // For each commit, which branch index it belongs to
	CommitCol    []int          // For each commit, which column it is in
	NumCols      int            // Total number of columns
	CommitMap    map[string]int // commit hash -> index
}

func buildGraph(data *GitData, model *BranchingModel, sparse bool, reverse bool) (*Graph, error) {
	commits := data.Commits

	branches := findBranches(commits, data.CommitMap, model)

	commitBranch := make([]int, len(commits))
	for i := range commitBranch {
		commitBranch[i] = -1
	}

	assignCommitsToBranches(commits, data.CommitMap, branches, commitBranch, model)

	numCols := assignColumns(branches)

	commitCol := make([]int, len(commits))
	for i, b := range commitBranch {
		if b >= 0 && b < len(branches) {
			commitCol[i] = branches[b].Column
		} else {
			commitCol[i] = -1
		}
	}

	assignColors(branches, model)

	g := &Graph{
		Commits:      commits,
		Branches:     branches,
		CommitBranch: commitBranch,
		CommitCol:    commitCol,
		NumCols:      numCols,
		CommitMap:    data.CommitMap,
	}

	return g, nil
}

func findBranches(commits []*CommitData, commitMap map[string]int, model *BranchingModel) []*Branch {
	var branches []*Branch
	branchByName := make(map[string]*Branch)

	for _, c := range commits {
		for _, ref := range c.Refs {
			if ref.IsTag {
				name := ref.Name
				if _, exists := branchByName[name]; !exists {
					b := &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99,
						SpawnIdx: -1,
					}
					branches = append(branches, b)
					branchByName[name] = b
				}
			} else if !ref.IsHEAD {
				name := ref.Name
				if _, exists := branchByName[name]; !exists {
					b := &Branch{
						Name:     name,
						HeadHash: c.Hash,
						Column:   99,
						SpawnIdx: -1,
					}
					branches = append(branches, b)
					branchByName[name] = b
				}
			}
		}
	}

	sort.SliceStable(branches, func(i, j int) bool {
		pi := model.GetPersistenceOrder(branches[i].Name)
		pj := model.GetPersistenceOrder(branches[j].Name)
		if pi != pj {
			return pi < pj
		}
		return branches[i].Name < branches[j].Name
	})

	for _, b := range branches {
		b.PersistIdx = model.GetPersistenceOrder(b.Name)
		b.OrderGroup = model.GetOrderGroup(b.Name)
	}

	return branches
}

func assignCommitsToBranches(commits []*CommitData, commitMap map[string]int, branches []*Branch, commitBranch []int, model *BranchingModel) {
	assigned := make([]bool, len(commits))

	// Build headToBranch: hash -> most-persistent branch index
	headToBranch := make(map[string]int)
	for bi, b := range branches {
		if !b.IsPseudo && b.HeadHash != "" {
			if existing, exists := headToBranch[b.HeadHash]; !exists {
				headToBranch[b.HeadHash] = bi
			} else if b.PersistIdx < branches[existing].PersistIdx {
				headToBranch[b.HeadHash] = bi
			}
		}
	}

	persistenceLen := len(model.Persistence)

	for bi := 0; bi < len(branches); bi++ {
		branch := branches[bi]

		if isTagBranch(branch.Name) {
			continue
		}

		// Find the branch head commit
		headIdx := -1
		for ci, c := range commits {
			if c.Hash == branch.HeadHash {
				headIdx = ci
				break
			}
		}

		if headIdx < 0 {
			continue
		}

		if assigned[headIdx] {
			continue
		}

		var branchCommits []int
		idx := headIdx
		for idx >= 0 && idx < len(commits) && !assigned[idx] {
			branchCommits = append(branchCommits, idx)
			assigned[idx] = true
			commitBranch[idx] = bi

			c := commits[idx]

			// Handle secondary parents
			for pi := 1; pi < len(c.Parents); pi++ {
				parentHash := c.Parents[pi]
				parentIdx, ok := commitMap[parentHash]
				if !ok {
					continue
				}
				if assigned[parentIdx] {
					continue
				}

				// Check if this secondary parent is the head of a persistent named branch
				secBranchIdx, isBranchHead := headToBranch[parentHash]
				if isBranchHead && branches[secBranchIdx].PersistIdx < persistenceLen {
					// Named branch with defined persistence -> skip, set SpawnIdx
					branches[secBranchIdx].SpawnIdx = idx
					continue
				}

				// Create a pseudo-branch
				pseudoBranch := &Branch{
					Name:     "unknown",
					HeadHash: parentHash,
					IsPseudo: true,
					Column:   99,
					SpawnIdx: idx,
				}

				pseudoIdx := parentIdx
				for pseudoIdx >= 0 && pseudoIdx < len(commits) && !assigned[pseudoIdx] {
					pseudoBranch.Commits = append(pseudoBranch.Commits, pseudoIdx)
					assigned[pseudoIdx] = true
					commitBranch[pseudoIdx] = len(branches)

					pc := commits[pseudoIdx]
					if len(pc.Parents) == 0 {
						break
					}
					nextHash := pc.Parents[0]
					nextIdx, ok2 := commitMap[nextHash]
					if !ok2 {
						break
					}
					pseudoIdx = nextIdx
				}

				if len(pseudoBranch.Commits) > 0 {
					pseudoBranch.Range = [2]int{pseudoBranch.Commits[0], pseudoBranch.Commits[len(pseudoBranch.Commits)-1]}
					for _, pci := range pseudoBranch.Commits {
						commitBranch[pci] = len(branches)
					}
					branches = append(branches, pseudoBranch)
				}
			}

			// Follow primary parent
			if len(c.Parents) == 0 {
				break
			}
			parentHash := c.Parents[0]
			nextIdx, ok := commitMap[parentHash]
			if !ok {
				break
			}
			idx = nextIdx
		}

		if len(branchCommits) > 0 {
			branch.Commits = branchCommits
			branch.Range = [2]int{branchCommits[0], branchCommits[len(branchCommits)-1]}
		}
	}

	// Set SpawnIdx for branches without one
	for _, b := range branches {
		if b.SpawnIdx < 0 && len(b.Commits) > 0 {
			b.SpawnIdx = b.Range[0]
		}
	}
}

func isTagBranch(name string) bool {
	return len(name) >= 5 && name[:5] == "tags/"
}

func assignColumns(branches []*Branch) int {
	type branchSort struct {
		idx        int
		start      int
		end        int
		length     int
		orderGroup int
	}

	var toSort []branchSort
	for i, b := range branches {
		if len(b.Commits) == 0 {
			b.Column = 99
			continue
		}
		visualStart := b.SpawnIdx
		if visualStart < 0 {
			visualStart = b.Range[0]
		}
		toSort = append(toSort, branchSort{
			idx:        i,
			start:      visualStart,
			end:        b.Range[1],
			length:     b.Range[1] - visualStart,
			orderGroup: b.OrderGroup,
		})
	}

	sort.SliceStable(toSort, func(i, j int) bool {
		a, b2 := toSort[i], toSort[j]
		if a.orderGroup != b2.orderGroup {
			return a.orderGroup < b2.orderGroup
		}
		if a.length != b2.length {
			return a.length < b2.length
		}
		return a.start < b2.start
	})

	type colInfo struct {
		lastEnd int
	}
	var cols []colInfo

	for _, bs := range toSort {
		b := branches[bs.idx]
		visualStart := bs.start

		col := -1
		for c, ci := range cols {
			if visualStart > ci.lastEnd {
				col = c
				break
			}
		}

		if col == -1 {
			col = len(cols)
			cols = append(cols, colInfo{bs.end})
		} else {
			cols[col].lastEnd = bs.end
		}

		b.Column = col
	}

	numCols := len(cols)
	if numCols == 0 {
		numCols = 1
	}
	return numCols
}

func assignColors(branches []*Branch, model *BranchingModel) {
	patternCount := make(map[string]int)

	for _, b := range branches {
		colorKey := ""
		for _, cm := range model.TerminalColors.Matches {
			if cm.Pattern.MatchString(b.Name) {
				colorKey = cm.Pattern.String()
				break
			}
		}
		if colorKey == "" {
			colorKey = "__unknown__"
		}

		count := patternCount[colorKey]
		patternCount[colorKey] = count + 1

		b.Color = model.GetTerminalColor(b.Name, count)
		b.SVGColor = model.GetSVGColor(b.Name, count)
		b.ColorIndex = count
	}
}
