// extendRangesForJoinPoints extends visual ranges for branches that share the same join point.
// When multiple branches connect to the same target commit, they all stay 'open'
// until the last one ends (for the combined connector row).
func extendRangesForJoinPoints(commits []*CommitData, commitMap map[string]int, branches []*Branch) {
	// Map: targetCommitHash -> []branchIdx (branches that connect to this target)
	targetToBranches := make(map[string][]int)

	for bi, b := range branches {
		if len(b.Commits) == 0 {
			continue
		}
		// Find the primary parent terminal (the commit this branch connects to)
		lastCommitIdx := b.Range[1]
		if lastCommitIdx < 0 || lastCommitIdx >= len(commits) {
			continue
		}
		lastCommit := commits[lastCommitIdx]
		if len(lastCommit.Parents) == 0 {
			continue
		}
		primaryParentHash := lastCommit.Parents[0]
		// Check if primary parent is in commitMap and assigned to a different branch
		_, ok := commitMap[primaryParentHash]
		if !ok {
			continue
		}
		targetToBranches[primaryParentHash] = append(targetToBranches[primaryParentHash], bi)
	}

	// For each target with multiple branches, extend all to the max Range[1]
	for _, branchIndices := range targetToBranches {
		if len(branchIndices) <= 1 {
			continue
		}
		maxEnd := -1
		for _, bi := range branchIndices {
			if branches[bi].Range[1] > maxEnd {
				maxEnd = branches[bi].Range[1]
			}
		}
		for _, bi := range branchIndices {
			if branches[bi].Range[1] < maxEnd {
				branches[bi].Range[1] = maxEnd
			}
		}
	}
}
GOEOF

