	// All connectors should connect to the same target (or we handle separately)
	// 
	// Find the leftmost target (destination) and rightmost source
	leftmostDst := numCols
	rightmostSrc := -1
	for _, conn := range connectors {
		if conn.DstCol < leftmostDst {
			leftmostDst = conn.DstCol
		}
		if conn.SrcCol > rightmostSrc {
			rightmostSrc = conn.SrcCol
		}
