# Let me now completely rewrite the render.go rendering logic
# The key insight: for multi-line formats, the rendering must:
# 1. Format text into lines first
# 2. Output first line with commit prefix
# 3. If there's a connector and we have more lines:
#    - Output connector prefix + second line
#    - Update active state (remove ended branches)
#    - Output remaining lines with post-connector prefix
# 4. If no connector:
#    - Output remaining lines with continuation prefix
#    - Then output any connector separately

# Let me write a more complete render.go

cat > /workspace/pkg/gitgraph/render.go << 'GOEOF'
package gitgraph

import (
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// SpawnInfo tracks which branches spawn from a merge commit
type SpawnInfo struct {
	BranchIdx int
	Column    int
}

// Connector represents a branch ending and connecting to its target
type Connector struct {
	SrcCol    int // Column of the ending branch
	DstCol    int // Column of the target
	SrcBranch int // Branch index
}

// renderText renders the graph as text
func renderText(g *Graph, model *BranchingModel, style StyleChars, format *CommitFormat, wrap *WrapConfig, useColor bool, debug bool, w io.Writer) error {
	numCols := g.NumCols
	if numCols == 0 {
		numCols = 1
	}

	graphWidth := 2*numCols + 2 // prefix width: 1(leading) + 2*N + 1(trailing)

	// Build spawn map: mergeCommitIdx -> branches spawned from it
	spawnAt := buildSpawnMap(g)

	for idx, c := range g.Commits {
		branchIdx := g.CommitBranch[idx]
		commitCol := -1
		if branchIdx >= 0 && branchIdx < len(g.Branches) {
			commitCol = g.Branches[branchIdx].Column
		}

		// Determine active columns at this commit
		activeAt := getActiveColumns(g, idx, numCols)

		// Determine merge spawns (for non-sparse mode)
		var mergeSpawns []SpawnInfo
		if c != nil && len(c.Parents) > 1 {
			if spawns, ok := spawnAt[idx]; ok {
				mergeSpawns = spawns
			}
		}

		// Build graph prefix for this commit
		prefix := buildCommitPrefix(commitCol, activeAt, mergeSpawns, numCols, style, useColor, g.Branches, branchIdx, len(c.Parents) > 1)
		_ = graphWidth

		// Find connectors after this commit
		connectors := findConnectors(g, idx)

		// Format commit text into lines
		textLines := formatCommitLines(c, format, useColor, branchIdx, g.Branches, model)

		// Determine post-connector active state
		var postActiveAt []bool
		if len(connectors) > 0 {
			postActiveAt = computePostConnectorActive(activeAt, connectors, numCols)
		}

		// Write the commit row (first line)
		if len(textLines) == 0 {
			fmt.Fprintln(w, prefix)
		} else {
			paddedPrefix := padTo(prefix, graphWidth)
			fmt.Fprintln(w, paddedPrefix+textLines[0])
		}

		// Write remaining lines
		if len(textLines) > 1 {
			isMultiLine := format.Kind == FormatShort || format.Kind == FormatMedium || format.Kind == FormatFull

			if len(connectors) > 0 && isMultiLine {
				// Merge connector with second text line
				connectorPrefix := buildConnectorPrefix(connectors, activeAt, numCols, style)
				paddedConnector := padTo(connectorPrefix, graphWidth)
				fmt.Fprintln(w, paddedConnector+textLines[1])

				// Remaining lines use post-connector active state
				contPrefix := buildContinuationPrefixFromActive(postActiveAt, numCols, style)
				for _, line := range textLines[2:] {
					fmt.Fprintln(w, padTo(contPrefix, graphWidth)+line)
				}
			} else {
				// No connector or single-line format: output remaining lines with continuation prefix
