	var connectors []Connector
	for bi, b := range g.Branches {
		if b.Column < 0 || b.Column >= g.NumCols {
			continue
		}
		if b.Range[1] != idx {
			continue
		}
		if len(b.Commits) == 0 {
			continue
		}
		lastCommitIdx := b.Range[1]
		// Make sure the last commit is actually a commit assigned to this branch
		if g.CommitBranch[lastCommitIdx] != bi {
			// Maybe Range[1] was extended - find the actual last commit
			actualLast := -1
			for _, ci := range b.Commits {
				if ci > actualLast {
					actualLast = ci
				}
