func buildCommitPrefix(commitCol int, active []bool, spawns []SpawnInfo, numCols int, style StyleChars, useColor bool, branches []*Branch, branchIdx int, isMerge bool) string {
	type cell struct {
		node  string
		right string
	}

	grid := make([]cell, numCols)

	// Initialize all columns
	for i := 0; i < numCols; i++ {
		if active[i] {
			grid[i].node = style.Vertical
		} else {
			grid[i].node = " "
		}
		grid[i].right = " "
	}

