	for _, b := range g.Branches {
		if b.Column >= 0 && b.Column < numCols {
			if b.SpawnIdx <= idx && idx <= b.Range[1] {
				active[b.Column] = true
			}
		}
	}
	return active
}

func computePostConnectorActive(active []bool, connectors []Connector, numCols int) []bool {
	post := make([]bool, numCols)
	copy(post, active)
	for _, conn := range connectors {
		if conn.SrcCol >= 0 && conn.SrcCol < numCols {
			post[conn.SrcCol] = false
		}
	}
	return post
}

func findConnectors(g *Graph, idx int) []Connector {
	var connectors []Connector
	for bi, b := range g.Branches {
		if b.Column < 0 || b.Column >= g.NumCols {
			continue
		}
		if b.Range[1] != idx {
			continue
		}
		if len(b.Commits) == 0 {
			continue
		}
		lastCommitIdx := b.Range[1]
		// Make sure the last commit is actually a commit assigned to this branch
		if g.CommitBranch[lastCommitIdx] != bi {
			// Maybe Range[1] was extended - find the actual last commit
			actualLast := -1
			for _, ci := range b.Commits {
				if ci > actualLast {
					actualLast = ci
				}
			}
			if actualLast < 0 {
				continue
			}
			lastCommitIdx = actualLast
		}
		lastCommit := g.Commits[lastCommitIdx]
		if len(lastCommit.Parents) == 0 {
			continue
		}
		primaryParentHash := lastCommit.Parents[0]
		parentIdx, ok := g.CommitMap[primaryParentHash]
		if !ok {
			continue
		}
		parentBranchIdx := g.CommitBranch[parentIdx]
		if parentBranchIdx < 0 || parentBranchIdx >= len(g.Branches) {
			continue
		}
		dstCol := g.Branches[parentBranchIdx].Column
		if dstCol == b.Column {
			continue
		}
		connectors = append(connectors, Connector{
			SrcCol:    b.Column,
			DstCol:    dstCol,
			SrcBranch: bi,
		})
	}
	return connectors
}

// buildCommitPrefix builds the graph prefix for a commit row
func buildCommitPrefix(commitCol int, active []bool, spawns []SpawnInfo, numCols int, style StyleChars, useColor bool, branches []*Branch, branchIdx int, isMerge bool) string {
	type cell struct {
		node  string
		right string
	}

	grid := make([]cell, numCols)

	// Initialize all columns
	for i := 0; i < numCols; i++ {
		if active[i] {
			grid[i].node = style.Vertical
		} else {
			grid[i].node = " "
		}
		grid[i].right = " "
	}

	// Set the commit column
	if commitCol >= 0 && commitCol < numCols {
		if isMerge && len(spawns) > 0 {
			grid[commitCol].node = style.MergeCommit
		} else {
			grid[commitCol].node = style.Commit
		}
	}

	// Handle merge spawns
	if len(spawns) > 0 && commitCol >= 0 {
		// Find the rightmost spawn (for the primary merge indicator)
		rightmost := -1
		for _, s := range spawns {
			if s.Column > commitCol && s.Column > rightmost {
				rightmost = s.Column
			}
		}

		if rightmost > commitCol {
			// Place merge arrow and branch top
			grid[commitCol].right = style.MergeRight
			for col := commitCol + 1; col < rightmost; col++ {
				grid[col].node = style.Horizontal
				grid[col].right = style.Horizontal
			}
			// The rightmost spawn is the last in the sequence
			// But intermediate spawns get special treatment
			// Actually for simplicity: just put '┐' at rightmost
			grid[rightmost].node = style.TopRight
			grid[rightmost].right = " "

			// For spawns that are NOT the rightmost but are to the right of commit
			// They just need the '┐' at their column? 
			// Actually looking at the output: for 2 merges, we see '○<──┐' for the first merge 
			// and '○<┐ │' for the second. The ─ fills columns between commit and the branch.
			// The branch '│' (col1) at the time of the second merge is ACTIVE (from first merge).
			// So the horizontal line handles it correctly.
		}
	}

	// Build the string
	var sb strings.Builder
	sb.WriteString(" ")
	for _, c := range grid {
		sb.WriteString(c.node)
		sb.WriteString(c.right)
	}
	sb.WriteString(" ")

	return sb.String()
}

func buildConnectorPrefix(connectors []Connector, activeAt []bool, numCols int, style StyleChars) string {
	type cell struct {
		node  string
		right string
	}
	grid := make([]cell, numCols)

	// Initialize: active columns get '│', inactive get ' '
	for i := 0; i < numCols; i++ {
		if activeAt[i] {
			grid[i].node = style.Vertical
			grid[i].right = " "
		} else {
			grid[i].node = " "
			grid[i].right = " "
		}
	}

	// Find leftmost dst and rightmost src for left-going connectors
	leftmostDst := numCols
	rightmostSrc := -1
	hasDstLeftOfSrc := false
	hasDstRightOfSrc := false

	for _, conn := range connectors {
		if conn.SrcCol > conn.DstCol {
			hasDstLeftOfSrc = true
			if conn.DstCol < leftmostDst {
				leftmostDst = conn.DstCol
			}
			if conn.SrcCol > rightmostSrc {
				rightmostSrc = conn.SrcCol
			}
		} else if conn.SrcCol < conn.DstCol {
			hasDstRightOfSrc = true
		}
	}

	// Handle left-going connectors (src > dst): pattern like ├─┴─┘
	if hasDstLeftOfSrc && leftmostDst < numCols {
		// Mark which columns end here (src columns)
		srcCols := make(map[int]bool)
		for _, conn := range connectors {
			if conn.SrcCol > conn.DstCol {
				srcCols[conn.SrcCol] = true
			}
		}

		// Set target column
		if activeAt[leftmostDst] {
			grid[leftmostDst].node = style.LeftCross // ├
		} else {
			grid[leftmostDst].node = style.BotLeft // └
		}
		grid[leftmostDst].right = style.Horizontal

		// Fill between target and rightmost src
		for col := leftmostDst + 1; col <= rightmostSrc; col++ {
			if col == rightmostSrc {
				grid[col].node = style.BotRight // ┘
				grid[col].right = " "
			} else if srcCols[col] {
				grid[col].node = style.BotCross // ┴
				grid[col].right = style.Horizontal
			} else {
				grid[col].node = style.Horizontal
				grid[col].right = style.Horizontal
			}
		}
	}

	// Handle right-going connectors (src < dst): pattern like └─┐
	if hasDstRightOfSrc {
		for _, conn := range connectors {
			if conn.SrcCol >= conn.DstCol {
				continue
			}
			src := conn.SrcCol
			dst := conn.DstCol

			grid[src].node = style.BotLeft
			grid[src].right = style.Horizontal
			for col := src + 1; col < dst; col++ {
				grid[col].node = style.Horizontal
				grid[col].right = style.Horizontal
			}
			grid[dst].node = style.TopRight
			grid[dst].right = " "
		}
	}

	// Build the string
	var sb strings.Builder
	sb.WriteString(" ")
	for _, c := range grid {
		sb.WriteString(c.node)
		sb.WriteString(c.right)
	}
	sb.WriteString(" ")

	return sb.String()
}

func buildContinuationPrefixFromActive(active []bool, numCols int, style StyleChars) string {
	var sb strings.Builder
	sb.WriteString(" ")
	for i := 0; i < numCols; i++ {
		if i < len(active) && active[i] {
			sb.WriteString(style.Vertical)
		} else {
			sb.WriteString(" ")
		}
		sb.WriteString(" ")
	}
	sb.WriteString(" ")
	return sb.String()
}

func padTo(s string, width int) string {
	vis := utf8.RuneCountInString(s)
	if vis >= width {
		return s
	}
	return s + strings.Repeat(" ", width-vis)
}

// formatCommitLines formats a commit into multiple text lines
func formatCommitLines(c *CommitData, format *CommitFormat, useColor bool, branchIdx int, branches []*Branch, model *BranchingModel) []string {
	if c == nil {
		return nil
	}

	var branchColor string
	if branchIdx >= 0 && branchIdx < len(branches) {
		branchColor = branches[branchIdx].Color
	}
	_ = branchColor

	var text string
	switch format.Kind {
	case FormatOneline:
		text = formatOnelineCommit(c, useColor, branchColor)
	case FormatShort:
		text = formatShortCommit(c, useColor, branchColor)
	case FormatMedium:
		text = formatMediumCommit(c, useColor, branchColor)
	case FormatFull:
		text = formatFullCommit(c, useColor, branchColor)
	case "custom":
		text = expandFormatString(format.Template, c, useColor, false)
	}

	if text == "" {
		return nil
	}

	lines := strings.Split(text, "\n")
	return lines
}

func printDebugInfo(g *Graph, w io.Writer) {
	for _, b := range g.Branches {
		var rangeStr string
		if len(b.Commits) == 0 {
			rangeStr = "((None, None))"
		} else {
			rangeStr = fmt.Sprintf("((Some(%d), Some(%d)))", b.Range[0], b.Range[1])
		}

		sStr := "None"
		if b.SpawnIdx >= 0 {
			sStr = fmt.Sprintf("Some(%d)", b.SpawnIdx)
		}
		tStr := "None"

		pseudoMark := ""
		if b.IsPseudo {
			pseudoMark = "m "
		}

		fmt.Fprintf(w, "%s (col %d) %s  %ss: %s, t: %s\n",
			b.Name, b.Column, rangeStr, pseudoMark, sStr, tStr)
	}
}
GOEOF

