// computePostCurrentCommitActive computes the active state for continuation lines.
// It removes branches that end at the current commit index.
func computePostCurrentCommitActive(g *Graph, idx int, active []bool, numCols int) []bool {
	post := make([]bool, numCols)
	copy(post, active)
	for _, b := range g.Branches {
		if b.Column >= 0 && b.Column < numCols {
			if b.Range[1] == idx {
				// This branch ends here (including extended ranges)
				// Check if the actual last commit of this branch is idx
				// (might be extended for visual purposes)
				post[b.Column] = false
			}
		}
	}
	return post
}
