// buildSparseSpawnPrefix builds the connector row for sparse mode merge commits
// In sparse mode, the merge arrows appear on a SEPARATE row below the merge commit
func buildSparseSpawnPrefix(commitCol int, spawns []SpawnInfo, activeAt []bool, numCols int, style StyleChars) string {
	type cell struct {
		node  string
		right string
	}
	grid := make([]cell, numCols)

	// Initialize: active columns get '│', inactive get ' '
	for i := 0; i < numCols; i++ {
		if activeAt[i] {
			grid[i].node = style.Vertical
			grid[i].right = " "
		} else {
			grid[i].node = " "
			grid[i].right = " "
		}
	}

	// Find the rightmost spawn column
	rightmost := -1
	for _, s := range spawns {
		if s.Column > commitCol && s.Column > rightmost {
			rightmost = s.Column
		}
	}

	if rightmost > commitCol {
		// Set commitCol: ├ (left-cross since line continues below)
		grid[commitCol].node = style.LeftCross
		grid[commitCol].right = style.MergeRight // <

		// Fill between commitCol and rightmost
		for col := commitCol + 1; col < rightmost; col++ {
			grid[col].node = style.Horizontal
			grid[col].right = style.Horizontal
		}

		// Set rightmost: ┐
		grid[rightmost].node = style.TopRight
		grid[rightmost].right = " "
	}

	// Build the string
	var sb strings.Builder
	sb.WriteString(" ")
	for _, c := range grid {
		sb.WriteString(c.node)
		sb.WriteString(c.right)
	}
	sb.WriteString(" ")

	return sb.String()
}
GOEOF

