				pos = parseColorSection(tokens, pos, &model.SVGColors)
			default:
				pos++
			}
			continue
		}

		// Top-level keys
		if tok.kind == tokIdent {
			key := tok.value
			pos++ // skip key
			if pos < len(tokens) && tokens[pos].kind == tokEquals {
