type ColorSection struct {
	Matches []ColorMatch
	Unknown []string
}

func parseColorSection(tokens []token, pos int, section *ColorSection) int {
	for pos < len(tokens) {
		tok := tokens[pos]

		// Stop at next section
		if tok.kind == tokLBracket {
			break
		}

		if tok.kind == tokIdent {
			key := tok.value
			pos++
			if pos < len(tokens) && tokens[pos].kind == tokEquals {
