	// Expect [
	if pos >= len(tokens) || tokens[pos].kind != tokLBracket {
		return pos
	}
	pos++ // skip [

	for pos < len(tokens) && tokens[pos].kind != tokRBracket {
		// Each match entry is [ pattern, [colors] ]
		if tokens[pos].kind == tokLBracket {
			pos++ // skip [

			// Parse pattern
			var pattern string
			if pos < len(tokens) && tokens[pos].kind == tokString {
				pattern = tokens[pos].value
				pos++
			}

			// Skip comma if present
			if pos < len(tokens) && tokens[pos].kind == tokComma {
				pos++
			}

			// Parse colors array
			var colors []string
			if pos < len(tokens) && tokens[pos].kind == tokLBracket {
				pos = parseStringArray(tokens, pos, &colors)
			}

			// Skip to end of this match entry (closing ])
			depth := 0
			for pos < len(tokens) {
				if tokens[pos].kind == tokLBracket {
					depth++
				} else if tokens[pos].kind == tokRBracket {
					if depth == 0 {
