func parseSectionHeader(tokens []token, pos int) string {
	if pos >= len(tokens) || tokens[pos].kind != tokLBracket {
		return ""
	}
	pos++
	var name strings.Builder
	for pos < len(tokens) && tokens[pos].kind != tokRBracket {
		if tokens[pos].kind == tokIdent {
			if name.Len() > 0 {
				name.WriteString("_")
			}
			name.WriteString(tokens[pos].value)
		} else if tokens[pos].kind == tokUnderscore {
			name.WriteString("_")
		}
		pos++
	}
	return name.String()
}

func parseSectionHeader2(tokens []token, pos int) int {
	// Skip to end of section header line
	for pos < len(tokens) && tokens[pos].kind != tokRBracket {
		pos++
	}
	if pos < len(tokens) {
		pos++ // skip ]
	}
	return pos
}

// Token types
type tokenKind int

const (
	tokIdent tokenKind = iota
	tokString
	tokLBracket
	tokRBracket
	tokEquals
	tokComma
	tokUnderscore
	tokDot
	tokOther
)

type token struct {
	kind  tokenKind
	value string
}

func tokenizeTOML(content string) []token {
	var tokens []token
	i := 0

	for i < len(content) {
		c := content[i]

		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '#':
			// Comment - skip to end of line
			for i < len(content) && content[i] != '\n' {
				i++
			}
		case c == '"':
			// Double-quoted string
			i++
			start := i
			for i < len(content) && content[i] != '"' {
				if content[i] == '\\' {
					i++
				}
				i++
			}
			tokens = append(tokens, token{tokString, content[start:i]})
			if i < len(content) {
				i++ // skip closing "
			}
		case c == '\'':
			// Single-quoted string
			i++
			start := i
			for i < len(content) && content[i] != '\'' {
				i++
			}
			tokens = append(tokens, token{tokString, content[start:i]})
			if i < len(content) {
				i++ // skip closing '
			}
		case c == '[':
			tokens = append(tokens, token{tokLBracket, "["})
			i++
		case c == ']':
			tokens = append(tokens, token{tokRBracket, "]"})
			i++
		case c == '=':
			tokens = append(tokens, token{tokEquals, "="})
			i++
		case c == ',':
			tokens = append(tokens, token{tokComma, ","})
			i++
		case c == '_':
			// Could be part of identifier
			start := i
			for i < len(content) && (isAlphaNum(content[i]) || content[i] == '_') {
				i++
			}
			tokens = append(tokens, token{tokIdent, content[start:i]})
		case isAlpha(c):
			start := i
			for i < len(content) && (isAlphaNum(content[i]) || content[i] == '_' || content[i] == '/') {
				i++
			}
			tokens = append(tokens, token{tokIdent, content[start:i]})
		default:
			i++
		}
	}

	return tokens
}

func isAlpha(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isAlphaNum(c byte) bool {
	return isAlpha(c) || (c >= '0' && c <= '9')
}
