// buildConnectorPrefixColored builds a colored connector prefix
func buildConnectorPrefixColored(connectors []Connector, activeAt []bool, numCols int, style StyleChars, useColor bool, colColors []string, g *Graph) string {
	type cell struct {
		node      string
		right     string
		nodeColor string
		rightColor string
	}
	grid := make([]cell, numCols)

	for i := 0; i < numCols; i++ {
		if activeAt[i] {
			grid[i].node = style.Vertical
			grid[i].nodeColor = colColors[i]
		} else {
			grid[i].node = " "
		}
		grid[i].right = " "
	}

	leftmostDst := numCols
	rightmostSrc := -1
	hasDstLeftOfSrc := false
	hasDstRightOfSrc := false

	for _, conn := range connectors {
		if conn.SrcCol > conn.DstCol {
			hasDstLeftOfSrc = true
			if conn.DstCol < leftmostDst {
				leftmostDst = conn.DstCol
			}
			if conn.SrcCol > rightmostSrc {
				rightmostSrc = conn.SrcCol
			}
		} else if conn.SrcCol < conn.DstCol {
			hasDstRightOfSrc = true
		}
	}

	if hasDstLeftOfSrc && leftmostDst < numCols {
		srcCols := make(map[int]bool)
		srcColors := make(map[int]string)
		for _, conn := range connectors {
			if conn.SrcCol > conn.DstCol {
				srcCols[conn.SrcCol] = true
				if conn.SrcBranch >= 0 && conn.SrcBranch < len(g.Branches) {
					srcColors[conn.SrcCol] = g.Branches[conn.SrcBranch].Color
				}
			}
		}

		// The rightmost source color is used for the horizontal line
		rightmostColor := srcColors[rightmostSrc]

		if activeAt[leftmostDst] {
			grid[leftmostDst].node = style.LeftCross
		} else {
			grid[leftmostDst].node = style.BotLeft
		}
		grid[leftmostDst].nodeColor = colColors[leftmostDst]
		grid[leftmostDst].right = style.Horizontal
		grid[leftmostDst].rightColor = rightmostColor

		for col := leftmostDst + 1; col <= rightmostSrc; col++ {
			if col == rightmostSrc {
				grid[col].node = style.BotRight
				grid[col].nodeColor = rightmostColor
				grid[col].right = " "
			} else if srcCols[col] {
				grid[col].node = style.BotCross
				grid[col].nodeColor = srcColors[col]
				grid[col].right = style.Horizontal
				grid[col].rightColor = rightmostColor
			} else {
				grid[col].node = style.Horizontal
				grid[col].nodeColor = rightmostColor
				grid[col].right = style.Horizontal
				grid[col].rightColor = rightmostColor
			}
		}
	}

	if hasDstRightOfSrc {
		for _, conn := range connectors {
			if conn.SrcCol >= conn.DstCol {
				continue
			}
			src := conn.SrcCol
			dst := conn.DstCol

			srcColor := ""
			if conn.SrcBranch >= 0 && conn.SrcBranch < len(g.Branches) {
				srcColor = g.Branches[conn.SrcBranch].Color
			}

			grid[src].node = style.BotLeft
			grid[src].nodeColor = srcColor
			grid[src].right = style.Horizontal
			grid[src].rightColor = srcColor
			for col := src + 1; col < dst; col++ {
				grid[col].node = style.Horizontal
				grid[col].nodeColor = srcColor
				grid[col].right = style.Horizontal
				grid[col].rightColor = srcColor
			}
			grid[dst].node = style.TopRight
			grid[dst].nodeColor = srcColor
			grid[dst].right = " "
		}
	}

	var sb strings.Builder
	sb.WriteString(" ")
	for _, c := range grid {
		sb.WriteString(colorChar(c.node, c.nodeColor, useColor))
		sb.WriteString(colorChar(c.right, c.rightColor, useColor))
	}
	sb.WriteString(" ")

	return sb.String()
}

// buildSparseSpawnPrefixColored builds a colored sparse spawn connector prefix
func buildSparseSpawnPrefixColored(commitCol int, spawns []SpawnInfo, activeAt []bool, numCols int, style StyleChars, useColor bool, colColors []string, branches []*Branch, branchIdx int) string {
	type cell struct {
		node      string
		right     string
		nodeColor string
		rightColor string
	}
	grid := make([]cell, numCols)

	for i := 0; i < numCols; i++ {
		if activeAt[i] {
			grid[i].node = style.Vertical
			grid[i].nodeColor = colColors[i]
		} else {
			grid[i].node = " "
		}
		grid[i].right = " "
	}

	commitColor := ""
	if branchIdx >= 0 && branchIdx < len(branches) {
		commitColor = branches[branchIdx].Color
	}

	rightmost := -1
	spawnColor := ""
	for _, s := range spawns {
		if s.Column > commitCol && s.Column > rightmost {
			rightmost = s.Column
			if s.BranchIdx >= 0 && s.BranchIdx < len(branches) {
				spawnColor = branches[s.BranchIdx].Color
			}
		}
	}

	if rightmost > commitCol {
		grid[commitCol].node = style.LeftCross
		grid[commitCol].nodeColor = commitColor
		grid[commitCol].right = style.MergeRight
		grid[commitCol].rightColor = spawnColor
		for col := commitCol + 1; col < rightmost; col++ {
			grid[col].node = style.Horizontal
			grid[col].nodeColor = spawnColor
			grid[col].right = style.Horizontal
			grid[col].rightColor = spawnColor
		}
		grid[rightmost].node = style.TopRight
		grid[rightmost].nodeColor = spawnColor
		grid[rightmost].right = " "
	}

	var sb strings.Builder
	sb.WriteString(" ")
	for _, c := range grid {
		sb.WriteString(colorChar(c.node, c.nodeColor, useColor))
		sb.WriteString(colorChar(c.right, c.rightColor, useColor))
	}
	sb.WriteString(" ")

	return sb.String()
}
GOEOF

