// branchColorFromModel gets the color for a branch name from the model
func branchColorFromModel(name string, branches []*Branch, model *BranchingModel) string {
	// First check if the branch is in our branch list
	for _, b := range branches {
		if b.Name == name {
			return b.Color
		}
	}
	// Fall back to model lookup
	if model != nil {
		return model.GetTerminalColor(name, 0)
	}
	return ""
}

// formatRefsStringColored formats refs with colors
func formatRefsStringColored(c *CommitData, useColor bool, localOnly bool, branches []*Branch, model *BranchingModel) string {
	if !useColor {
		return formatRefsString(c, false, localOnly)
	}

	var branchParts []string
	var tagParts []string

	headTarget := ""
	for _, r := range c.Refs {
		if r.IsHEAD {
			headTarget = r.HeadTarget
		}
	}

	headAdded := false
	for _, r := range c.Refs {
		if r.IsHEAD {
			continue
		}
		if r.IsTag {
			tagName := strings.TrimPrefix(r.Name, "tags/")
			// Color tags with master/tag color
			tagColor := branchColorFromModel("tags/"+tagName, branches, model)
			if tagColor == "" {
				tagColor = branchColorFromModel(r.Name, branches, model)
			}
			if tagColor == "" && model != nil {
				tagColor = model.GetTerminalColor("tags/"+tagName, 0)
			}
			tagParts = append(tagParts, "["+colorize(tagName, tagColor)+"]")
		} else {
			if localOnly && r.IsRemote {
				continue
			}
			branchColor := branchColorFromModel(r.Name, branches, model)
			if branchColor == "" {
				branchColor = "bright_cyan"
			}
			if r.Name == headTarget && !headAdded {
				headRef := colorize("HEAD ->", "bright_cyan") + " " + colorize(r.Name, branchColor)
				branchParts = append([]string{headRef}, branchParts...)
				headAdded = true
			} else {
				branchParts = append(branchParts, colorize(r.Name, branchColor))
			}
		}
	}

	if headTarget != "" && !headAdded {
		headColor := branchColorFromModel(headTarget, branches, model)
		if headColor == "" {
			headColor = "bright_cyan"
		}
		branchParts = append([]string{colorize("HEAD ->", "bright_cyan") + " " + colorize(headTarget, headColor)}, branchParts...)
	}

	var result []string

	if len(branchParts) > 0 {
		branchStr := "(" + strings.Join(branchParts, ", ") + ")"
		result = append(result, branchStr)
	}

	result = append(result, tagParts...)

	return strings.Join(result, " ")
}

// formatOnelineCommitColored formats a commit in oneline format with colors
func formatOnelineCommitColored(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel) string {
	var sb strings.Builder

	abbr := c.Hash[:7]
	if useColor {
		sb.WriteString(colorize(abbr, "bright_yellow"))
	} else {
		sb.WriteString(abbr)
	}

	refsStr := formatRefsStringColored(c, useColor, false, branches, model)
	if refsStr != "" {
		sb.WriteString(" ")
		sb.WriteString(refsStr)
	}

	if c.Subject != "" {
		sb.WriteString(" ")
		sb.WriteString(c.Subject)
	}

	return sb.String()
}

// formatShortCommitColored formats a commit in short format with colors
func formatShortCommitColored(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsStringColored(c, useColor, false, branches, model)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	if len(c.Parents) > 1 {
		var abbrs []string
		for _, p := range c.Parents {
			if len(p) >= 7 {
				abbrs = append(abbrs, p[:7])
			}
		}
		sb.WriteString("\nMerge: " + strings.Join(abbrs, " "))
	}

	sb.WriteString("\nAuthor: " + c.AuthorName + " <" + c.AuthorEmail + ">")
	sb.WriteString("\n")
	sb.WriteString("\n    " + c.Subject)
	sb.WriteString("\n")

	return sb.String()
}

// formatMediumCommitColored formats a commit in medium format with colors
func formatMediumCommitColored(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsStringColored(c, useColor, false, branches, model)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	if len(c.Parents) > 1 {
		var abbrs []string
		for _, p := range c.Parents {
			if len(p) >= 7 {
				abbrs = append(abbrs, p[:7])
			}
		}
		sb.WriteString("\nMerge: " + strings.Join(abbrs, " "))
	}

	sb.WriteString("\nAuthor: " + c.AuthorName + " <" + c.AuthorEmail + ">")
	sb.WriteString("\nDate:   " + formatDate(c.AuthorDate))
	sb.WriteString("\n")
	sb.WriteString("\n    " + c.Subject)
	sb.WriteString("\n")

	if c.Body != "" {
		sb.WriteString("\n    " + strings.Replace(c.Body, "\n", "\n    ", -1))
		sb.WriteString("\n")
	}

	return sb.String()
}

// formatFullCommitColored formats a commit in full format with colors
func formatFullCommitColored(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsStringColored(c, useColor, false, branches, model)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	if len(c.Parents) > 1 {
		var abbrs []string
		for _, p := range c.Parents {
			if len(p) >= 7 {
				abbrs = append(abbrs, p[:7])
			}
		}
		sb.WriteString("\nMerge: " + strings.Join(abbrs, " "))
	}

	sb.WriteString("\nAuthor: " + c.AuthorName + " <" + c.AuthorEmail + ">")
	sb.WriteString("\nCommit: " + c.CommitterName + " <" + c.CommitterEmail + ">")
	sb.WriteString("\nDate:   " + formatDate(c.AuthorDate))
	sb.WriteString("\n")
	sb.WriteString("\n    " + c.Subject)
	sb.WriteString("\n")

	if c.Body != "" {
		sb.WriteString("\n    " + strings.Replace(c.Body, "\n", "\n    ", -1))
		sb.WriteString("\n")
	}

	return sb.String()
}
