package gitgraph

import (
	"strings"
)

// formatRefsColorFull formats refs with full color support
func formatRefsColorFull(c *CommitData, useColor bool, localOnly bool, branches []*Branch, model *BranchingModel, commitBranchColor string) string {
	if !useColor {
		return formatRefsString(c, false, localOnly)
	}

	var branchParts []string
	var tagParts []string

	headTarget := ""
	for _, r := range c.Refs {
		if r.IsHEAD {
			headTarget = r.HeadTarget
		}
	}

	headAdded := false
	for _, r := range c.Refs {
		if r.IsHEAD {
			continue
		}
		if r.IsTag {
			tagName := strings.TrimPrefix(r.Name, "tags/")
			tagColor := commitBranchColor
			if tagColor == "" && model != nil {
				tagColor = model.GetTerminalColor("tags/"+tagName, 0)
			}
			tagParts = append(tagParts, "["+colorize(tagName, tagColor)+"]")
		} else {
			if localOnly && r.IsRemote {
				continue
			}
			branchColor := branchColorFromModel(r.Name, branches, model)
			if branchColor == "" {
				branchColor = "bright_cyan"
			}
			if r.Name == headTarget && !headAdded {
				headRef := colorize("HEAD ->", "bright_cyan") + " " + colorize(r.Name, branchColor)
				branchParts = append([]string{headRef}, branchParts...)
				headAdded = true
			} else {
				branchParts = append(branchParts, colorize(r.Name, branchColor))
			}
		}
	}

	if headTarget != "" && !headAdded {
		headColor := branchColorFromModel(headTarget, branches, model)
		if headColor == "" {
			headColor = "bright_cyan"
		}
		branchParts = append([]string{colorize("HEAD ->", "bright_cyan") + " " + colorize(headTarget, headColor)}, branchParts...)
	}

	var result []string
	if len(branchParts) > 0 {
		branchStr := "(" + strings.Join(branchParts, ", ") + ")"
		result = append(result, branchStr)
	}
	result = append(result, tagParts...)
	return strings.Join(result, " ")
}

// formatOnelineCommitColoredFull formats a commit in oneline format with full colors
func formatOnelineCommitColoredFull(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel, commitBranchColor string) string {
	var sb strings.Builder

	abbr := c.Hash[:7]
	if useColor {
		sb.WriteString(colorize(abbr, "bright_yellow"))
	} else {
		sb.WriteString(abbr)
	}

	refsStr := formatRefsColorFull(c, useColor, false, branches, model, commitBranchColor)
	if refsStr != "" {
		sb.WriteString(" ")
		sb.WriteString(refsStr)
	}

	if c.Subject != "" {
		sb.WriteString(" ")
		sb.WriteString(c.Subject)
	}

	return sb.String()
}

func formatShortCommitColoredFull(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel, commitBranchColor string) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsColorFull(c, useColor, false, branches, model, commitBranchColor)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	if len(c.Parents) > 1 {
		var abbrs []string
		for _, p := range c.Parents {
			if len(p) >= 7 {
				abbrs = append(abbrs, p[:7])
			}
		}
		sb.WriteString("\nMerge: " + strings.Join(abbrs, " "))
	}

	sb.WriteString("\nAuthor: " + c.AuthorName + " <" + c.AuthorEmail + ">")
	sb.WriteString("\n")
	sb.WriteString("\n    " + c.Subject)
	sb.WriteString("\n")

	return sb.String()
}

func formatMediumCommitColoredFull(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel, commitBranchColor string) string {
	var sb strings.Builder

	hashLine := "commit " + c.Hash
	refsStr := formatRefsColorFull(c, useColor, false, branches, model, commitBranchColor)
	if refsStr != "" {
		hashLine += " " + refsStr
	}
	sb.WriteString(hashLine)

	if len(c.Parents) > 1 {
