	if c.Body != "" {
		sb.WriteString("\n    " + strings.Replace(c.Body, "\n", "\n    ", -1))
		sb.WriteString("\n")
	}

	return sb.String()
}

func formatFullCommitColoredFull(c *CommitData, useColor bool, branches []*Branch, model *BranchingModel, commitBranchColor string) string {
	var sb strings.Builder

