package gitgraph

import (
	"fmt"
	"io"
)

const (
	svgRowHeight   = 15
	svgColWidth    = 15
	svgNodeRadius  = 4
	svgMargin      = 15
)

// renderSVG renders the graph as SVG
func renderSVG(g *Graph, model *BranchingModel, w io.Writer) error {
	numCols := g.NumCols
	numCommits := len(g.Commits)

	// Calculate dimensions
	// Width: (numCols+1) * colWidth
	// Height: numCommits * rowHeight + margin
	width := (numCols + 1) * svgColWidth
	height := numCommits*svgRowHeight + svgMargin

	fmt.Fprintf(w, "<svg height=\"%d\" viewBox=\"0 0 %d %d\" width=\"%d\" xmlns=\"http://www.w3.org/2000/svg\">\n",
		height, width, height, width)

	// For each commit, output: outgoing connections (lines/paths) then circle
	for idx, c := range g.Commits {
		if c == nil {
			continue
		}

		branchIdx := g.CommitBranch[idx]
		if branchIdx < 0 || branchIdx >= len(g.Branches) {
			continue
		}
		b := g.Branches[branchIdx]
		col := b.Column
		if col < 0 || col >= numCols {
			continue
		}

		x := (col + 1) * svgColWidth
		y := (idx + 1) * svgRowHeight
		color := b.SVGColor

		isMerge := len(c.Parents) > 1
		circleFill := color
		if isMerge {
			circleFill = "white"
		}

		// 1. Vertical line to next commit in same branch
		nextBranchCommitY := findNextBranchCommitY(g, branchIdx, idx)
		if nextBranchCommitY > 0 {
			fmt.Fprintf(w, "<line stroke=\"%s\" stroke-width=\"1\" x1=\"%d\" x2=\"%d\" y1=\"%d\" y2=\"%d\"/>\n",
				color, x, x, y, nextBranchCommitY)
		}

		// 2. Spawn paths for merge commits (to secondary parents)
		if isMerge {
			for pi := 1; pi < len(c.Parents); pi++ {
				parentHash := c.Parents[pi]
				parentIdx, ok := g.CommitMap[parentHash]
				if !ok {
					continue
				}
				parentBranchIdx := g.CommitBranch[parentIdx]
				if parentBranchIdx < 0 || parentBranchIdx >= len(g.Branches) {
					continue
				}
				spawnBranch := g.Branches[parentBranchIdx]
				spawnCol := spawnBranch.Column
				if spawnCol < 0 {
					continue
				}
				destX := (spawnCol + 1) * svgColWidth
				destY := (parentIdx + 1) * svgRowHeight
				spawnColor := spawnBranch.SVGColor

				// Spawn path formula:
				// M x,y L x,y Q x,y_mid x_mid,y_mid Q destX,y_mid destX,y+15 L destX,destY
				nextRowY := y + svgRowHeight
				yMid := float64(y+nextRowY) / 2.0
				xMid := float64(x+destX) / 2.0

				fmt.Fprintf(w, "<path d=\"M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d\" fill=\"none\" stroke=\"%s\" stroke-width=\"1\"/>\n",
					x, y, x, y, x, yMid, xMid, yMid, destX, yMid, destX, nextRowY, destX, destY, spawnColor)
			}
		}

		// 3. Merge-back path if this is the last commit in the branch
		// AND primary parent is in a different column
		if b.Range[1] == idx {
			// This is the last actual commit in the branch
			actualLastCommit := idx
			// Verify by checking if this commit is actually in the branch
			isLastActual := false
			for _, ci := range b.Commits {
				if ci == actualLastCommit {
					isLastActual = true
					break
				}
			}
			if isLastActual && len(c.Parents) > 0 {
				primaryParentHash := c.Parents[0]
				parentIdx, ok := g.CommitMap[primaryParentHash]
				if ok {
					parentBranchIdx := g.CommitBranch[parentIdx]
					if parentBranchIdx >= 0 && parentBranchIdx < len(g.Branches) {
						destBranch := g.Branches[parentBranchIdx]
						destCol := destBranch.Column
						if destCol != col {
							destX := (destCol + 1) * svgColWidth
							destY := (parentIdx + 1) * svgRowHeight

							// Merge-back path formula:
							// If destY == y+15 (adjacent): M x,y L x,y Q x,y_mid x_mid,y_mid Q destX,y_mid destX,destY L destX,destY
							// If destY > y+15 (gap): M x,y L x,destY-15 Q x,y_mid x_mid,y_mid Q destX,y_mid destX,destY L destX,destY
							prevDestY := destY - svgRowHeight
							xMid := float64(x+destX) / 2.0
							yMid := float64(prevDestY+destY) / 2.0

							if prevDestY <= y {
								// No straight line part
								yMid = float64(y+destY) / 2.0
								fmt.Fprintf(w, "<path d=\"M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d\" fill=\"none\" stroke=\"%s\" stroke-width=\"1\"/>\n",
									x, y, x, y, x, yMid, xMid, yMid, destX, yMid, destX, destY, destX, destY, color)
							} else {
								// Straight line down then bezier
								fmt.Fprintf(w, "<path d=\"M%d,%d L%d,%d Q%d,%.1f,%.1f,%.1f Q%d,%.1f,%d,%d L%d,%d\" fill=\"none\" stroke=\"%s\" stroke-width=\"1\"/>\n",
									x, y, x, prevDestY, x, yMid, xMid, yMid, destX, yMid, destX, destY, destX, destY, color)
							}
						}
					}
				}
			}
		}

		// 4. Draw the circle
		fmt.Fprintf(w, "<circle cx=\"%d\" cy=\"%d\" fill=\"%s\" r=\"%d\" stroke=\"%s\" stroke-width=\"1\"/>\n",
			x, y, circleFill, svgNodeRadius, color)
	}

	fmt.Fprintln(w, "</svg>")
	return nil
}

// findNextBranchCommitY finds the Y coordinate of the next commit in the same branch
func findNextBranchCommitY(g *Graph, branchIdx int, currentIdx int) int {
	b := g.Branches[branchIdx]

	// Find the next commit in the same branch (in display order)
	for i := currentIdx + 1; i < len(g.Commits); i++ {
		if g.CommitBranch[i] == branchIdx {
			return (i + 1) * svgRowHeight
		}
	}
	return 0 // No next commit in same branch
}
