func getEffectiveName(b *Branch) string {
	if b.IsRemote() {
		// Use 'fork/' prefix for remote branches
		// e.g., origin/feature/x -> fork/feature/x (removes remote name prefix)
		parts := splitRemoteName(b.Name)
		return "fork/" + parts
	}
	return b.Name
