func (b *Branch) IsRemote() bool {
	// A branch is remote if its name contains '/' AND matches remote branch patterns
	// We detect this by checking if the branch was set as IsRemote during ref parsing
	// Since we don't store IsRemote on Branch directly, check if name starts with 'origin/' or similar
	// Actually: for this, we need to check if the branch is a remote ref
	// We'll check if the RefInfo had IsRemote set
