// splitRemoteName removes the remote name prefix from a remote branch
func splitRemoteName(name string) string {
	// "origin/feature/x" -> "feature/x"
	// "upstream/main" -> "main"
	slashIdx := -1
	for i, c := range name {
		if c == '/' {
			slashIdx = i
			break
		}
	}
	if slashIdx < 0 {
		return name
	}
	return name[slashIdx+1:]
}

