	// For each branch, get its effective name for color matching
	for _, b := range branches {
		// Get the effective name for color matching
		// Remote branches get fork/ prefix
		effectiveName := b.Name
		if b.IsRemoteBranch {
			effectiveName = "fork/" + splitRemoteName(b.Name)
		}

		// Find color key (pattern string that matches)
		colorKey := ""
		for _, cm := range model.TerminalColors.Matches {
